func TestFixedRetentionKeepsTheFullBackupThroughoutItsCadence(t *testing.T) {
	var history []oci.CloudVolumeBackup
	for day := range 15 {
		at := now.Add(time.Duration(day) * 24 * time.Hour)
		actions := Plan(scope, volume, history, at)
		var created bool
		for _, action := range actions {
			switch action.Kind {
			case ActionCreate:
				created = true
				want := TypeIncremental
				if day%7 == 0 {
					want = TypeFull
				}
				if action.Type != want {
					t.Fatalf("day %d: backup type %s, want %s", day, action.Type, want)
				}
				history = append(history, oci.CloudVolumeBackup{ID: action.Key, VolumeID: volume,
					LifecycleState: "AVAILABLE", Type: action.Type, CreatedAt: at, FreeformTags: scope.Tags(volume, action.Key)})
			case ActionDelete:
				for i, backup := range history {
					if backup.ID == action.BackupID {
						history = append(history[:i], history[i+1:]...)
						break
					}
				}
			}
		}
		if !created {
			t.Fatalf("day %d: no daily backup", day)
		}
		full := false
		for _, backup := range history {
			if backup.Type == TypeFull {
				full = true
			}
		}
		if !full || len(history) > 8 {
			t.Fatalf("day %d: retained history has no FULL or exceeds retention plus the new backup: %+v", day, history)
		}
	}
}

func TestPlanUsesANewAttemptKeyAfterAFaultyBackup(t *testing.T) {
	first := Plan(scope, volume, nil, now)
	if len(first) != 1 || first[0].Kind != ActionCreate {
		t.Fatalf("first plan = %+v", first)
	}
	faulty := oci.CloudVolumeBackup{ID: "f1", VolumeID: volume, LifecycleState: "FAULTY", Type: TypeFull,
		CreatedAt: now.Add(-time.Minute), FreeformTags: scope.Tags(volume, first[0].Key)}
	second := Plan(scope, volume, []oci.CloudVolumeBackup{faulty}, now.Add(15*time.Minute))
	if len(second) != 1 || second[0].Key == first[0].Key {
		t.Fatalf("replacement after FAULTY replays the failed key: %+v", second)
	}
	if again := Plan(scope, volume, []oci.CloudVolumeBackup{faulty}, now.Add(30*time.Minute)); again[0].Key != second[0].Key {
		t.Fatal("the replacement key is not stable while its outcome is ambiguous")
	}
	faulty2 := faulty
	faulty2.ID, faulty2.FreeformTags = "f2", scope.Tags(volume, second[0].Key)
	third := Plan(scope, volume, []oci.CloudVolumeBackup{faulty, faulty2}, now.Add(45*time.Minute))
	if third[0].Key == second[0].Key || third[0].Key == first[0].Key {
		t.Fatalf("a second failure did not advance the attempt: %+v", third)
	}
}

func TestRunnerChecksYoungOrphanSourcesOnceIncludingFailures(t *testing.T) {
	for _, readErr := range []error{nil, errors.New("OCI source unreadable")} {
		provider := newFakeProvider(orphan("young-a", "removed", time.Hour), orphan("young-b", "removed", 2*time.Hour))
		provider.goneErr = map[string]error{"removed": readErr}
		runner := runner(provider, &fakeFencer{snapshot: leader()})
		runner.Volumes = func(context.Context) ([]string, error) { return nil, nil }
		report, err := runner.RunOnce(t.Context())
		if (err != nil) != (readErr != nil) || provider.goneReads["removed"] != 1 || len(provider.deletes) != 0 || len(report.Deleted) != 0 {
			t.Fatalf("young orphan observation: reads=%v deletes=%v report=%+v err=%v", provider.goneReads, provider.deletes, report, err)
		}
	}
}

func TestRunnerProtectsPlacedVolumeAfterSourceObservationFailure(t *testing.T) {
	provider := newFakeProvider(owned("backup", "AVAILABLE", TypeFull, 31*24*time.Hour))
	provider.goneErr = map[string]error{volume: errors.New("OCI source unreadable")}
	runner := runner(provider, &fakeFencer{snapshot: leader()})
	runner.Volumes = func(context.Context) ([]string, error) { return []string{volume, "ocid1.volume.readable"}, nil }
	report, err := runner.RunOnce(t.Context())
	if err == nil || len(provider.deletes) != 0 || provider.goneReads[volume] != 1 || provider.creates != 1 || len(report.Created) != 1 {
		t.Fatalf("unreadable placed source: creates=%d deletes=%v reads=%v report=%+v err=%v", provider.creates, provider.deletes, provider.goneReads, report, err)
	}
}

func TestRunnerRecognizesTerminatedPlacedVolumesWithoutCreatingBackups(t *testing.T) {
	for _, age := range []time.Duration{time.Hour, 31 * 24 * time.Hour} {
		t.Run(age.String(), func(t *testing.T) {
			provider := newFakeProvider(owned("backup", "AVAILABLE", TypeFull, age))
			provider.gone = map[string]bool{volume: true}
			report, err := runner(provider, &fakeFencer{snapshot: leader()}).RunOnce(t.Context())
			wantDeleted := 0
			if age >= orphanRetention {
				wantDeleted = 1
			}
			if err != nil || provider.creates != 0 || len(provider.deletes) != wantDeleted || len(report.Deleted) != wantDeleted {
				t.Fatalf("terminated placed volume: creates=%d deletes=%v report=%+v err=%v", provider.creates, provider.deletes, report, err)
			}
		})
	}
}

func TestCollectorMeasuresTargetsAndReportsPartialFailures(t *testing.T) {
	failure := errors.New("no such mount")
	collector := Collector{
		Cell: "gru", Node: "host-a", Now: func() time.Time { return observed },
		Targets: []Target{
			{Role: storage.RoleBoot, Path: "/"},
			{Role: storage.RoleJetStream, Path: "/var/lib/nats", Reserve: func(context.Context) (uint64, error) { return 3 * gib, nil }},
			{Role: storage.RoleTerraBaseData, Path: "/missing", VolumeID: "ocid1.volume.x"},
		},
		Statfs: func(path string) (FSStat, error) {
			if path == "/missing" {
				return FSStat{}, failure
			}
			return FSStat{TotalBytes: 100 * gib, FreeBytes: 40 * gib, AvailBytes: 35 * gib, InodesTotal: 100, InodesFree: 50}, nil
		},
	}
	usages, err := collector.Collect(t.Context())
	if !errors.Is(err, failure) || len(usages) != 2 {
		t.Fatalf("collect = %+v, %v", usages, err)
	}
	if usages[0].UsedBytes != 60*gib || usages[0].AvailBytes != 35*gib || usages[1].ReservedBytes != 3*gib {
		t.Fatalf("unexpected measurements: %+v", usages)
	}
}

func TestEvaluateFloorsAndReservations(t *testing.T) {
	small := usage(storage.RoleBoot, 10*gib, 2*gib, gib/2)
	if got := Evaluate(small, Policy{}); got.Level != LevelCritical || !strings.Contains(got.Reason, "floor") {
		t.Fatalf("free-space floor not enforced: %+v", got)
	}
	inodes := usage(storage.RoleBoot, 100*gib, 10*gib, 90*gib)
	inodes.InodesFree = 10
	if got := Evaluate(inodes, Policy{}); got.Level != LevelCritical {
		t.Fatalf("inode floor not enforced: %+v", got)
	}
	// 40 GiB used, 60 GiB free, but JetStream may still claim 50 GiB of it.
	store := usage(storage.RoleJetStream, 100*gib, 40*gib, 60*gib)
	store.ReservedBytes = 50 * gib
	if got := Evaluate(store, Policy{}); got.Level != LevelScaleOut || got.Utilization < 0.89 {
		t.Fatalf("reservation not counted as used: %+v", got)
	}
	store.ReservedBytes = 70 * gib
	if got := Evaluate(store, Policy{}); got.Level != LevelCritical {
		t.Fatalf("unbacked JetStream reservation is not critical: %+v", got)
	}
}

func TestEvaluateThresholds(t *testing.T) {
	cases := []struct {
		name string
		used uint64
		want Level
	}{
		{"half", 50, LevelOK},
		{"warn", 72, LevelWarn},
		{"scale-out", 86, LevelScaleOut},
		{"refuse", 96, LevelCritical},
	}
	for _, test := range cases {
		signal := Evaluate(usage(storage.RoleTerraBaseData, 100*gib, test.used*gib, (100-test.used)*gib), Policy{})
		if signal.Level != test.want {
			t.Fatalf("%s: level %s (%.2f), want %s", test.name, signal.Level, signal.Utilization, test.want)
		}
		if test.want != LevelOK && signal.Reason == "" {
			t.Fatalf("%s: signal has no reason", test.name)
		}
	}
}

func TestNodeHeadroomSubtractsAJetStreamReserveOnTheBootFilesystem(t *testing.T) {
	boot := usage(storage.RoleBoot, 100*gib, 60*gib, 40*gib)
	shared := usage(storage.RoleJetStream, 100*gib, 60*gib, 40*gib)
	shared.ReservedBytes = 8 * gib
	headroom, ok := NodeHeadroomBytes([]Signal{Evaluate(boot, Policy{}), Evaluate(shared, Policy{})}, "host-a")
	if !ok || headroom != 32*gib {
		t.Fatalf("shared-filesystem headroom = %d %v, want the 8 GiB JetStream reserve subtracted", headroom, ok)
	}
	separate := usage(storage.RoleJetStream, 200*gib, 60*gib, 140*gib)
	separate.ReservedBytes = 8 * gib
	headroom, ok = NodeHeadroomBytes([]Signal{Evaluate(boot, Policy{}), Evaluate(separate, Policy{})}, "host-a")
	if !ok || headroom != 40*gib {
		t.Fatalf("separate-filesystem headroom = %d %v, want the full boot headroom", headroom, ok)
	}
	exhausted := shared
	exhausted.ReservedBytes = 80 * gib
	if headroom, _ := NodeHeadroomBytes([]Signal{Evaluate(boot, Policy{}), Evaluate(exhausted, Policy{})}, "host-a"); headroom != 0 {
		t.Fatalf("over-reserved headroom = %d, want 0", headroom)
	}
}

func TestPolicyValidation(t *testing.T) {
	if err := (Policy{}).Validate(); err != nil {
		t.Fatal(err)
	}
	for _, bad := range []Policy{
		{WarnPercent: 90, ScaleOutPercent: 80, RefusePercent: 95},
		{WarnPercent: 70, ScaleOutPercent: 85, RefusePercent: 101},
		{WarnPercent: -1},
	} {
		if err := bad.Validate(); err == nil {
			t.Fatalf("invalid policy accepted: %+v", bad)
		}
	}
}

