func TestDrainProtocolPeer(t *testing.T) {
	directory := os.Getenv("TS_EXECUTION_DRAIN_PEER")
	if directory == "" {
		return
	}
	raw, err := os.ReadFile(filepath.Join(directory, "binding"))
	if err != nil {
		t.Fatal(err)
	}
	var binding peerBinding
	if err := json.Unmarshal(raw, &binding); err != nil {
		t.Fatal(err)
	}
	if binding.Backup {
		serveBackupPeer(t, directory)
		return
	}
	listener, err := net.Listen("unix", filepath.Join(directory, "control", "member.sock"))
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(listener.Addr().String(), 0o602); err != nil {
		t.Fatal(err)
	}
	process := memberstatus.Process{PID: os.Getpid(), StartNonce: strings.Repeat("1", 32)}
	err = http.Serve(listener, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		challenge := r.URL.Query().Get("nonce")
		code := http.StatusOK
		var reply any
		switch r.URL.Path {
		case "/v1/member/status":
			reply = memberstatus.Status{SchemaVersion: 2, Nonce: challenge, Process: process, Scope: binding.Scope, Authority: binding.Authority, Local: memberstatus.Local{StorageRecovered: true, ReplicationListenerReady: true, Healthy: true, Ready: true}, Serving: true, Capabilities: memberstatus.Capabilities{ServingProof: true, DurableDrain: true}}
		case "/v1/member/serving-proof":
			reply = memberstatus.ServingProof{SchemaVersion: 1, Nonce: challenge, Process: process, Scope: binding.Scope, Authority: binding.Authority, Serving: true, Listeners: memberstatus.Listeners{Client: true, Replication: true}, Object: memberstatus.ObjectProof{RootSHA256: strings.Repeat("5", 64), TargetSHA256: strings.Repeat("6", 64), InboxArchiveSHA256AtRecovery: strings.Repeat("8", 64), LocalSourceSequence: 12, RemoteInboxDurableSequence: 9, RemoteAppliedSequence: 9}, Replication: memberstatus.ReplicationProof{LocalSourceSequence: 12, PeerMemberID: binding.Survivor.MemberID, PeerIncarnation: binding.Survivor.Incarnation, CurrentAuthenticated: true, PeerDurableSequence: 12, PeerAppliedSequence: 12, LocalInboxDurableSequence: 9, LocalInboxAppliedSequence: 9}}
		case "/v1/member/drain", "/v1/member/drain-status":
			path := filepath.Join(directory, "peer-request")
			var request memberstatus.DrainRequest
			if r.Method == http.MethodPost {
				body, err := io.ReadAll(r.Body)
				if err != nil {
					panic(err)
				}
				if err := os.WriteFile(path, body, 0o600); err != nil {
					panic(err)
				}
			}
			body, err := os.ReadFile(path)
			if errors.Is(err, os.ErrNotExist) {
				code = http.StatusNotFound
				reply = map[string]string{"state": "absent"}
				break
			}
			if err != nil {
				panic(err)
			}
			if err := json.Unmarshal(body, &request); err != nil {
				panic(err)
			}
			if r.Method == http.MethodPost {
				challenge = request.Nonce
			}
			mode, err := os.ReadFile(filepath.Join(directory, "mode"))
			if err != nil {
				panic(err)
			}
			envelope := memberstatus.DrainEnvelope{SchemaVersion: 1, Nonce: challenge, Process: process, OperationID: request.OperationID, State: "pending"}
			if string(mode) == "pending" {
				code = http.StatusAccepted
				reply = envelope
				break
			}
			applied := uint64(15)
			if string(mode) == "lag" {
				applied = 14
			}
			receipt := memberstatus.DrainReceipt{SchemaVersion: 1, OperationID: request.OperationID, RequestNonce: request.Nonce, RequestedProcess: request.Expected.Process, DrainedProcess: process, Scope: binding.Scope, Authority: binding.Authority, LocalSourceOrigin: memberstatus.Origin{MemberID: binding.Scope.MemberID, Incarnation: binding.Scope.Incarnation}, LocalSourceDurableSequence: 15, ArchivedSourceSequence: 15, ObjectRootSHA256: strings.Repeat("5", 64), Peer: memberstatus.DrainPeer{Origin: memberstatus.Origin{MemberID: binding.Survivor.MemberID, Incarnation: binding.Survivor.Incarnation}, DurableSequence: 15, AppliedSequence: applied, LocalInboxDurableSequence: 9, LocalInboxAppliedSequence: 9}, ReplicationQuiesced: true}
			canonical, err := json.Marshal(receipt)
			if err != nil {
				panic(err)
			}
			sum := sha256.Sum256(canonical)
			digest := hex.EncodeToString(sum[:])
			envelope.State = "complete"
			envelope.Receipt = &receipt
			envelope.ReceiptSHA256 = &digest
			reply = envelope
		default:
			code = http.StatusNotFound
			reply = map[string]string{"state": "absent"}
		}
		body, err := json.Marshal(reply)
		if err != nil {
			panic(err)
		}
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("Content-Length", strconv.Itoa(len(body)))
		w.WriteHeader(code)
		_, _ = w.Write(body)
	}))
	if err != nil {
		t.Fatal(err)
	}
}

func TestStatefulQualificationHTTPIntegration(t *testing.T) {
	ctx, cancel := context.WithTimeout(t.Context(), 15*time.Second)
	defer cancel()
	rootPublic, root, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	qualifierPublic, qualifier, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	signerPublic, signer, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	signerID, _ := trust.KeyID(signerPublic)
	rootID, _ := trust.KeyID(rootPublic)
	qualifierID, _ := trust.KeyID(qualifierPublic)
	roots := trust.Keyring{rootID: rootPublic, qualifierID: qualifierPublic}
	now := time.Now().UTC().Truncate(time.Second)
	target := release.ContainerTarget{Cell: "GRU", Environment: "production", Role: "terrabase", Architecture: "amd64"}
	data := RetainedData{DatabaseID: entityid.Derive("database", "fixture"), PartitionID: entityid.Derive("partition", "fixture"), VolumeID: "ocid1.volume.fixture", FileSystemUUID: "12345678-1234-1234-1234-123456789abc", FileSystemType: "ext4", DiskFormatSHA256: strings.Repeat("d", 64), SourceArtifactSHA256: strings.Repeat("e", 64), SourceTreeSHA256: strings.Repeat("f", 64), SourceArchitecture: "amd64"}
	cpu := CPUProfile{Architecture: "amd64", FeaturesSHA256: strings.Repeat("c", 64)}
	var lock sync.RWMutex
	blobs := make(map[string][]byte)
	put := func(wire []byte) string {
		digest := fmt.Sprintf("%x", sha256.Sum256(wire))
		lock.Lock()
		blobs[digest] = wire
		lock.Unlock()
		return digest
	}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		lock.RLock()
		wire, ok := blobs[strings.TrimPrefix(r.URL.Path, "/evidence/")]
		lock.RUnlock()
		if !ok {
			http.NotFound(w, r)
			return
		}
		_, _ = w.Write(wire)
	}))
	defer server.Close()
	open := func(ctx context.Context, digest string) (io.ReadCloser, error) {
		request, err := http.NewRequestWithContext(ctx, http.MethodGet, server.URL+"/evidence/"+digest, nil)
		if err != nil {
			return nil, err
		}
		response, err := server.Client().Do(request)
		if err != nil {
			return nil, err
		}
		if response.StatusCode != http.StatusOK {
			response.Body.Close()
			return nil, fmt.Errorf("evidence HTTP %d", response.StatusCode)
		}
		return response.Body, nil
	}
	sign := func(value any, scope trust.Scope, key ed25519.PrivateKey) []byte {
		t.Helper()
		payload, err := trust.EncodePayload(value)
		if err != nil {
			t.Fatal(err)
		}
		envelope, err := trust.Sign(payload, scope, now, now.Add(time.Hour), key)
		if err != nil {
			t.Fatal(err)
		}
		wire, err := trust.EncodeEnvelope(envelope)
		if err != nil {
			t.Fatal(err)
		}
		return wire
	}
	migration := release.SequenceMigration{Schema: release.SequenceMigrationSchema, Namespace: "fixture", Bucket: "gru-1-head", Region: "GRU", SignerKeyID: signerID, SignerPublicKey: base64.RawURLEncoding.EncodeToString(signerPublic), Role: target.Role, Environment: target.Environment, SequenceFloor: 100}
	for _, cell := range []string{"GRU", "SFO", "FRA"} {
		migration.Regions = append(migration.Regions, release.SequenceFloor{Cell: cell, RunNumber: 100, EvidenceSHA256: strings.Repeat("1", 64)})
	}
	migrationEnvelope, err := release.SignSequenceMigration(migration, now, root)
	if err != nil {
		t.Fatal(err)
	}
	migrationWire, err := trust.EncodeEnvelope(migrationEnvelope)
	if err != nil {
		t.Fatal(err)
	}
	migrationSHA, err := trust.Fingerprint(migrationEnvelope)
	if err != nil {
		t.Fatal(err)
	}
	grant, err := trust.SignDelegation(trust.Delegation{SchemaVersion: trust.SchemaVersion, SubjectKeyID: signerID, SubjectPublicKey: base64.RawURLEncoding.EncodeToString(signerPublic), Capabilities: []trust.Capability{{Domain: release.ContainerClaimDomain, DeploymentID: release.ContainerScope(target).DeploymentID, Cell: target.Cell, Environment: target.Environment, Role: target.Role, Slots: []string{"linux-amd64"}, Actions: []string{"sign"}}}}, now, now.Add(time.Hour), root)
	if err != nil {
		t.Fatal(err)
	}
	grantWire, err := trust.EncodeEnvelope(grant)
	if err != nil {
		t.Fatal(err)
	}
	proof := StatefulQualification{Schema: StatefulQualificationSchema, CandidateSourceTreeSHA256: strings.Repeat("b", 64), Data: data, SourceCPU: cpu, TargetCPU: cpu, DiskFormatSHA256: data.DiskFormatSHA256}
	proof.ResultData = data
	configWire := []byte(fmt.Sprintf(`{"architecture":"%s","os":"linux","config":{"Entrypoint":["/usr/local/bin/terrabase"],"User":"65532:65532"},"rootfs":{"type":"layers","diff_ids":[]}}`, runtime.GOARCH))
	configSHA := put(configWire)
	manifestWire := []byte(fmt.Sprintf(`{"schemaVersion":2,"config":{"mediaType":"application/vnd.oci.image.config.v1+json","digest":"sha256:%s","size":%d},"layers":[]}`, configSHA, len(configWire)))
	imageDigest := put(manifestWire)
	indexWire := []byte(fmt.Sprintf(`{"schemaVersion":2,"mediaType":"application/vnd.oci.image.index.v1+json","manifests":[{"mediaType":"application/vnd.oci.image.manifest.v1+json","digest":"sha256:%s","size":%d,"platform":{"architecture":"%s","os":"linux"}}]}`, imageDigest, len(manifestWire), runtime.GOARCH))
	indexSHA := put(indexWire)
	proof.ImageManifest = release.ProductionGateEvidence{Gate: "image-manifest", SHA256: imageDigest, Bytes: int64(len(manifestWire)), CompletedAt: now}
	proof.ImageConfig = release.ProductionGateEvidence{Gate: "image-config", SHA256: configSHA, Bytes: int64(len(configWire)), CompletedAt: now}
	proof.ResultData.SourceArtifactSHA256 = imageDigest
	proof.ResultData.SourceTreeSHA256 = proof.CandidateSourceTreeSHA256
	for _, gate := range []string{"retained-restart", "restore", "replication-catchup", "durable-drain", "sigterm", "cpu-format-transition"} {
		wire := []byte("controlled test-only " + gate + " evidence")
		proof.Scenarios = append(proof.Scenarios, release.ProductionGateEvidence{Gate: gate, SHA256: put(wire), Bytes: int64(len(wire)), CompletedAt: now})
	}
	allocations := statefulSequenceLocation(t)
	if err := allocations.ImportMigration(ctx, migrationEnvelope, roots, target.Role, target.Environment, now); err != nil {
		t.Fatal(err)
	}
	makeBundle := func(p StatefulQualification) release.ContainerBundle {
		t.Helper()
		wire, err := trust.EncodePayload(p)
		if err != nil {
			t.Fatal(err)
		}
		claim := release.ContainerClaim{Schema: release.ContainerClaimSchema, Image: "registry.example/platform/terrabase@sha256:" + imageDigest, SourceRepository: "https://github.com/TerraScale/terrascale", SourceRevision: strings.Repeat("a", 40), SourceTreeSHA256: proof.CandidateSourceTreeSHA256, Cell: target.Cell, Environment: target.Environment, Role: target.Role, Architecture: target.Architecture, ReleaseSequence: 101, SequenceMigrationSHA256: migrationSHA, QualificationSHA256: indexSHA}
		ha := []byte("controlled runtime fixture evidence")
		expected := release.ProductionExpectation{SourceRevision: claim.SourceRevision, ArtifactSHA256: imageDigest, QualificationSHA256: claim.QualificationSHA256, Cell: target.Cell, Environment: target.Environment, Role: target.Role, Architecture: target.Architecture, Runtime: release.ProductionRuntime}
		qualification := release.ProductionQualification{Schema: release.ProductionQualificationSchema, Candidate: expected, Evidence: []release.ProductionGateEvidence{{Gate: "runtime-ha", SHA256: put(ha), Bytes: int64(len(ha)), CompletedAt: now}, {Gate: "workload-safety", SHA256: put(wire), Bytes: int64(len(wire)), CompletedAt: now}}}
		claim.Production.Qualification = sign(qualification, release.ProductionQualificationScope(expected), qualifier)
		family, err := claim.WorkerFamilyDigest()
		if err != nil {
			t.Fatal(err)
		}
		sequence, sequenceWire, err := allocations.AllocateWithEvidence(ctx, release.SequenceIdentity{Role: claim.Role, Environment: claim.Environment, SourceRevision: claim.SourceRevision, ManifestSHA256: family}, roots, signer)
		if err != nil {
			t.Fatal(err)
		}
		claim.ReleaseSequence = sequence
		return release.ContainerBundle{Index: indexWire, Sequence: sequenceWire, Claim: sign(claim, release.ContainerScope(target), signer), Migration: migrationWire, Delegation: grantWire}
	}
	bundle := makeBundle(proof)
	verified, err := VerifyStatefulCurrent(ctx, bundle, roots, target, data, cpu, now, now.Add(time.Minute), open, allocations)
	if err != nil || verified.Data() != data || verified.CPU() != cpu || verified.SHA256() == "" {
		t.Fatalf("signed typed consumer: %+v %v", verified, err)
	}

	retained, err := VerifyRetainedProvenance(ctx, bundle, roots, target, proof.ResultData, open, allocations)
	if err != nil || retained != proof.ResultData {
		t.Fatalf("signed prior writer provenance: %+v %v", retained, err)
	}
	unknownFormat := proof.ResultData
	unknownFormat.DiskFormatSHA256 = ""
	retained, err = VerifyRetainedProvenance(ctx, bundle, roots, target, unknownFormat, open, allocations)
	if err != nil || retained.DiskFormatSHA256 != proof.ResultData.DiskFormatSHA256 {
		t.Fatalf("format derived only from signed retained result: %+v %v", retained, err)
	}
	wrongVolume := proof.ResultData
	wrongVolume.VolumeID = "ocid1.volume.foreign"
	if _, err := VerifyRetainedProvenance(ctx, bundle, roots, target, wrongVolume, open, allocations); err == nil {
		t.Fatal("retained proof transplanted to another volume")
	}
	t.Run("initial-native-provenance", func(t *testing.T) {
		// Read real ELF bytes; the fixture never executes a TerraBase executable.
		nativeBytes, err := os.ReadFile("/bin/sh")
		if err != nil {
			t.Fatal(err)
		}
		nativeProof := proof
		nativeProof.Data.SourceArtifactSHA256 = put(nativeBytes)
		nativeProof.SourceArtifact = &release.ProductionGateEvidence{Gate: "native-source-artifact", SHA256: nativeProof.Data.SourceArtifactSHA256, Bytes: int64(len(nativeBytes)), CompletedAt: now}
		expected := nativeProof.Data
		expected.DiskFormatSHA256 = ""
		expected.SourceArchitecture = ""
		retained, err := VerifyNativeRetainedProvenance(ctx, makeBundle(nativeProof), roots, target, expected, now, now.Add(time.Minute), open, allocations)
		if err != nil || retained != nativeProof.Data {
			t.Fatalf("exact native artifact bridge: %+v %v", retained, err)
		}
		expected.VolumeID = "ocid1.volume.foreign"
		if _, err := VerifyNativeRetainedProvenance(ctx, makeBundle(nativeProof), roots, target, expected, now, now.Add(time.Minute), open, allocations); err == nil {
			t.Fatal("native proof transplanted to other volume")
		}
		if _, err := VerifyNativeRetainedProvenance(ctx, bundle, roots, target, data, now, now.Add(time.Minute), open, allocations); err == nil {
			t.Fatal("native source bytes omitted")
		}
		otherArchitecture := "arm64"
		if runtime.GOARCH == "arm64" {
			otherArchitecture = "amd64"
		}
		nativeProof.Data.SourceArchitecture = otherArchitecture
		nativeProof.SourceCPU.Architecture = otherArchitecture
		if _, err := VerifyStatefulCurrent(ctx, makeBundle(nativeProof), roots, target, nativeProof.Data, cpu, now, now.Add(time.Minute), open, allocations); err == nil {
			t.Fatal("native ELF machine changed by a signed claim")
		}
	})
	for _, test := range []struct {
		name   string
		mutate func(*StatefulQualification)
	}{
		{"source-tree", func(p *StatefulQualification) { p.CandidateSourceTreeSHA256 = strings.Repeat("9", 64) }},
		{"retained-volume", func(p *StatefulQualification) { p.Data.VolumeID = "ocid1.volume.other" }},
		{"disk-format", func(p *StatefulQualification) { p.DiskFormatSHA256 = strings.Repeat("8", 64) }},
		{"cpu-features", func(p *StatefulQualification) { p.TargetCPU.FeaturesSHA256 = strings.Repeat("7", 64) }},
		{"missing-restore", func(p *StatefulQualification) { p.Scenarios = append(p.Scenarios[:1], p.Scenarios[2:]...) }},
		{"future-scenario", func(p *StatefulQualification) { p.Scenarios[0].CompletedAt = now.Add(time.Second) }},
	} {
		t.Run(test.name, func(t *testing.T) {
			candidate := proof
			candidate.Scenarios = append([]release.ProductionGateEvidence(nil), proof.Scenarios...)
			test.mutate(&candidate)
			if _, err := VerifyStatefulCurrent(ctx, makeBundle(candidate), roots, target, data, cpu, now, now.Add(time.Minute), open, allocations); err == nil {
				t.Fatal("invalid signed stateful proof admitted")
			}
		})
	}
	if _, err := VerifyStatefulCurrent(ctx, bundle, roots, target, data, cpu, now, now.Add(2*time.Hour), open, allocations); err == nil {
		t.Fatal("expired proof admitted")
	}
	lock.Lock()
	blobs[proof.Scenarios[0].SHA256] = []byte("changed retained scenario")
	lock.Unlock()
	if _, err := VerifyStatefulCurrent(ctx, bundle, roots, target, data, cpu, now, now.Add(time.Minute), open, allocations); err == nil {
		t.Fatal("tampered nested retained scenario admitted")
	}
	lock.Lock()
	delete(blobs, proof.Scenarios[0].SHA256)
	lock.Unlock()
	if _, err := VerifyStatefulCurrent(ctx, bundle, roots, target, data, cpu, now, now.Add(time.Minute), open, allocations); err == nil {
		t.Fatal("missing nested retained scenario admitted")
	}
}

func TestRuntimeObserverHostNetworkNamespaceIntegration(t *testing.T) {
	if os.Getenv("TS_RUNTIME_NETWORK_FIXTURE") == "private" {
		parent := os.Getppid()
		if err := verifyHostNetworkNamespace(parent); err == nil {
			t.Fatal("a process in another network namespace accepted as host networking")
		}
		return
	}
	if err := verifyHostNetworkNamespace(os.Getpid()); err != nil {
		t.Fatal(err)
	}
	executable, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	command := exec.CommandContext(t.Context(), "sudo", "-n", "env", "TS_RUNTIME_NETWORK_FIXTURE=private", "nice", "-n", "19", "unshare", "--net", executable, "-test.run=^TestRuntimeObserverHostNetworkNamespaceIntegration$", "-test.v")
	if output, err := command.CombinedOutput(); err != nil {
		t.Fatalf("kernel network namespace refusal: %v\n%s", err, output)
	}
}

