	mu        sync.Mutex
	published []VolumeUsage
}

func (publisher *recordingPublisher) Publish(_ context.Context, usage VolumeUsage) error {
	publisher.mu.Lock()
	defer publisher.mu.Unlock()
	publisher.published = append(publisher.published, usage)
