func NewClient(socket string, scope Scope, authority Authority, observe ObserveProcess) (*Client, error) {
	if socket == "" || !filepath.IsAbs(socket) || filepath.Clean(socket) != socket ||
		!scope.valid() || !authority.valid() || observe == nil {
		return nil, errors.New("incomplete signed member control binding")
	}
	return &Client{socket: socket, scope: scope, authority: authority, observe: observe}, nil
}

member_status.text:
func (c *Client) Status(ctx context.Context) (Status, error) {
	challenge, err := nonce()
	if err != nil {
		return Status{}, err
	}
	code, body, process, err := c.exchange(ctx, http.MethodGet, "/v1/member/status?nonce="+challenge, nil)
	if err != nil {
		return Status{}, err
	}
	if code != http.StatusOK {
		return Status{}, fmt.Errorf("member status HTTP %d", code)
	}
	// The load block is telemetry, never evidence: it is split off before
	// the strict decode, and a malformed, incomplete or out-of-range block
	// is dropped instead of failing the status.
	evidence, load := SplitLoad(body)
	var status Status
	if err := decodeRequired(evidence, &status, statusPaths...); err != nil {
		return Status{}, err
	}
	status.Load = DecodeLoad(load)
	if status.SchemaVersion != 2 || status.Nonce != challenge || status.Process.PID != process.ProtocolPID() ||
		!status.Process.valid() || status.Scope != c.scope || status.Authority != c.authority ||
		!status.Capabilities.ServingProof || !status.Capabilities.DurableDrain {
		return Status{}, ErrStaleBinding
	}
	if status.Serving && (status.ReceiverOnly || !status.Local.StorageRecovered ||
		!status.Local.ReplicationListenerReady || !status.Local.Healthy || !status.Local.Ready) {
		return Status{}, ErrNotServing
	}
	status.verified = true
	return status, nil
}

member_proof.text:
func (c *Client) servingProof(ctx context.Context, status Status, peerMemberID, peerIncarnation string) (ServingProof, error) {
	if !status.verified || !canonicalID(peerMemberID) || peerMemberID == c.scope.MemberID ||
		status.Scope != c.scope || status.Authority != c.authority || !status.Process.valid() ||
		status.ReceiverOnly || !status.Serving || !status.Local.StorageRecovered ||
		!status.Local.ReplicationListenerReady || !status.Local.Healthy || !status.Local.Ready {
		return ServingProof{}, ErrNotServing
	}
	challenge, err := nonce()
	if err != nil {
		return ServingProof{}, err
	}
	code, body, process, err := c.exchange(ctx, http.MethodGet, "/v1/member/serving-proof?nonce="+challenge, nil)
	if err != nil {
		return ServingProof{}, err
	}
	if code == http.StatusServiceUnavailable {
		return ServingProof{}, ErrNotServing
	}
	if code != http.StatusOK {
		return ServingProof{}, fmt.Errorf("member serving proof HTTP %d", code)
	}
	proof, err := decodeServingProof(body)
	if err != nil {
		return ServingProof{}, err
	}
	if proof.SchemaVersion != 1 || proof.Nonce != challenge || proof.Process != status.Process ||
		proof.Process.PID != process.ProtocolPID() || proof.Scope != c.scope || proof.Authority != c.authority ||
		!proof.Serving || !proof.Listeners.Client || !proof.Listeners.Replication ||
		!lowerHex(proof.Object.RootSHA256, 64) || !lowerHex(proof.Object.TargetSHA256, 64) ||
		!lowerHex(proof.Object.InboxArchiveSHA256AtRecovery, 64) ||
		proof.Object.RemoteAppliedSequence > proof.Object.RemoteInboxDurableSequence ||
		proof.Replication.PeerMemberID != peerMemberID || !lowerHexIdentity(proof.Replication.PeerIncarnation) ||
		peerIncarnation != "" && proof.Replication.PeerIncarnation != peerIncarnation ||
		!proof.Replication.CurrentAuthenticated ||
		proof.Replication.LocalSourceSequence != proof.Object.LocalSourceSequence ||
		proof.Replication.PeerAppliedSequence < proof.Replication.LocalSourceSequence ||
		!proof.Replication.ordered() {
		return ServingProof{}, ErrNotServing
	}
	proof.verified = true
	return proof, nil
}

member_socket.text:
func inspectSocket(path string, process ProcessObservation) (socketSnapshot, error) {
	parentInfo, err := os.Lstat(filepath.Dir(path))
	if err != nil {
		return socketSnapshot{}, err
	}
	socketInfo, err := os.Lstat(path)
	if err != nil {
		return socketSnapshot{}, err
	}
	parent, parentOK := parentInfo.Sys().(*syscall.Stat_t)
	socket, socketOK := socketInfo.Sys().(*syscall.Stat_t)
	if !parentOK || !socketOK || !parentInfo.IsDir() || socketInfo.Mode()&os.ModeSocket == 0 ||
		parent.Uid != 0 || parent.Gid != process.GID || parent.Mode&0o7777 != 0o730 ||
		socket.Uid != process.UID || socket.Gid != process.GID || socket.Mode&0o7777 != 0o602 {
		return socketSnapshot{}, errors.New("unsafe member control socket ownership or mode")
	}
	return socketSnapshot{parent: *parent, socket: *socket}, nil
}

member_exchange.text:
func (c *Client) exchangeBounded(ctx context.Context, method, path string, requestBody []byte,
	maxResponse int64, timeout time.Duration,
) (int, []byte, ProcessObservation, error) {
	if maxResponse <= 0 || maxResponse > 64<<10 || len(requestBody) > 64<<10 {
		return 0, nil, ProcessObservation{}, errors.New("member control request or response bound is invalid")
	}
	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	before, err := c.observe(ctx)
	if err != nil {
		return 0, nil, ProcessObservation{}, fmt.Errorf("unverified native member process: %w", err)
	}
	if before.PID < 2 || before.UID == 0 || before.GID == 0 || before.KernelStart == "" || before.Cgroup == "" {
		return 0, nil, ProcessObservation{}, errors.New("unverified native member process")
	}
	if before.namespace.wirePID != 0 {
		bound, err := BindPIDNamespace(before, before.namespace.initPID)
		if err != nil || bound != before {
			return 0, nil, ProcessObservation{}, ErrStaleBinding
		}
	}
	pathBefore, err := inspectSocket(c.socket, before)
	if err != nil {
		return 0, nil, ProcessObservation{}, err
	}
	var peerPID atomic.Int64
	transport := &http.Transport{
		DisableKeepAlives: true, DisableCompression: true, MaxResponseHeaderBytes: 4096,
		DialContext: func(dialCtx context.Context, _, _ string) (net.Conn, error) {
			conn, err := (&net.Dialer{}).DialContext(dialCtx, "unix", c.socket)
			if err != nil {
				return nil, err
			}
			credentials, err := peerCredentials(conn)
			if err == nil && (credentials.Pid != int32(before.PID) || credentials.Uid != before.UID || credentials.Gid != before.GID) {
				err = ErrStaleBinding
			}
			if err == nil {
				var current socketSnapshot
				current, err = inspectSocket(c.socket, before)
				if err == nil && !pathBefore.same(current) {
					err = ErrStaleBinding
				}
			}
			if err != nil {
				_ = conn.Close()
				return nil, err
			}
			peerPID.Store(int64(credentials.Pid))
			return conn, nil
		},
	}
	defer transport.CloseIdleConnections()
	request, err := http.NewRequestWithContext(ctx, method, "http://unix"+path, bytes.NewReader(requestBody))
	if err != nil {
		return 0, nil, ProcessObservation{}, err
	}
	if method == http.MethodPost {
		request.Header.Set("Content-Type", "application/json")
	}
	response, err := (&http.Client{Transport: transport, CheckRedirect: func(*http.Request, []*http.Request) error {
		return http.ErrUseLastResponse
	}}).Do(request)
	if err != nil {
		return 0, nil, ProcessObservation{}, fmt.Errorf("member control request: %w", err)
	}
	defer response.Body.Close()
	if response.Header.Get("Content-Type") != "application/json" || response.ContentLength < 0 ||
		response.ContentLength > maxResponse || len(response.TransferEncoding) != 0 {
		return 0, nil, ProcessObservation{}, errors.New("invalid member control HTTP response")
	}
	body, err := io.ReadAll(io.LimitReader(response.Body, maxResponse+1))
	if err != nil || len(body) != int(response.ContentLength) || int64(len(body)) > maxResponse {
		return 0, nil, ProcessObservation{}, errors.New("invalid member control response length")
	}
	if peerPID.Load() != int64(before.PID) {
		return 0, nil, ProcessObservation{}, ErrStaleBinding
	}
	pathAfter, err := inspectSocket(c.socket, before)
	if err != nil || !pathBefore.same(pathAfter) {
		return 0, nil, ProcessObservation{}, ErrStaleBinding
	}
	after, err := c.observe(ctx)
	if err != nil || after != before {
		return 0, nil, ProcessObservation{}, ErrStaleBinding
	}
	return response.StatusCode, body, before, nil
}

peercred.text:
func peerCredentials(conn net.Conn) (*unix.Ucred, error) {
	unixConn, ok := conn.(*net.UnixConn)
	if !ok {
		return nil, errors.New("member control connection is not Unix")
	}
	raw, err := unixConn.SyscallConn()
	if err != nil {
		return nil, err
	}
	var credentials *unix.Ucred
	var readErr error
	if err := raw.Control(func(fd uintptr) {
		credentials, readErr = unix.GetsockoptUcred(int(fd), unix.SOL_SOCKET, unix.SO_PEERCRED)
	}); err != nil {
		return nil, err
	}
	return credentials, readErr
}

member_store.text:
func NewFileStore(path string) (*FileStore, error) {
	if path == "" || !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return nil, errors.New("member drain record path must be absolute and clean")
	}
	dir, err := os.Lstat(filepath.Dir(path))
	if err != nil {
		return nil, err
	}
	stat, ok := dir.Sys().(*syscall.Stat_t)
	if !ok || !dir.IsDir() || stat.Uid != uint32(os.Geteuid()) || dir.Mode().Perm() != 0o700 {
		return nil, errors.New("member drain record directory ownership or mode is unsafe")
	}
	return &FileStore{path: path}, nil
}

member_load.text:
func (s *FileStore) Load() (DrainRecord, bool, error) {
	var record DrainRecord
	var found bool
	err := s.locked(func() error {
		var err error
		record, found, err = s.loadUnlocked()
		return err
	})
	return record, found, err
}

member_create.text:
func (s *FileStore) Create(record DrainRecord) error {
	if !record.valid(record.Request.Expected.Scope, record.Request.Expected.Authority) {
		return ErrStaleBinding
	}
	return s.locked(func() error {
		current, found, err := s.loadUnlocked()
		if err != nil {
			return err
		}
		if found {
			if current != record {
				return ErrOperationConflict
			}
			return nil
		}
		data, err := json.Marshal(record)
		if err != nil {
			return err
		}
		if len(data) > maxRecordBytes {
			return errors.New("member drain record exceeds bound")
		}
		directory := filepath.Dir(s.path)
		temp, err := os.CreateTemp(directory, ".member-drain-*")
		if err != nil {
			return err
		}
		defer os.Remove(temp.Name())
		if err := temp.Chmod(0o600); err != nil {
			_ = temp.Close()
			return err
		}
		if _, err := temp.Write(data); err != nil {
			_ = temp.Close()
			return err
		}
		if err := temp.Sync(); err != nil {
			_ = temp.Close()
			return err
		}
		if err := temp.Close(); err != nil {
			return err
		}
		if err := os.Rename(temp.Name(), s.path); err != nil {
			return err
		}
		dir, err := os.Open(directory)
		if err != nil {
			return err
		}
		defer dir.Close()
		return dir.Sync()
	})
}

member_load_unlocked.text:
func (s *FileStore) loadUnlocked() (DrainRecord, bool, error) {
	info, err := os.Lstat(s.path)
	if errors.Is(err, os.ErrNotExist) {
		return DrainRecord{}, false, nil
	}
	if err != nil {
		return DrainRecord{}, false, err
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.Mode().IsRegular() || stat.Nlink != 1 || stat.Uid != uint32(os.Geteuid()) || info.Mode().Perm() != 0o600 || info.Size() > maxRecordBytes {
		return DrainRecord{}, false, errors.New("unsafe member drain record")
	}
	file, err := os.Open(s.path)
	if err != nil {
		return DrainRecord{}, false, err
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, maxRecordBytes+1))
	if err != nil || len(data) > maxRecordBytes {
		return DrainRecord{}, false, errors.New("invalid member drain record length")
	}
	var record DrainRecord
	if err := decodeRequired(data, &record, "request.schema_version", "request.operation_id", "request.nonce",
		"request.expected.process.pid", "request.expected.process.start_nonce",
		"request.expected.scope.cluster_id", "request.expected.scope.tenant_id", "request.expected.scope.database_id",
		"request.expected.scope.shard_id", "request.expected.scope.member_id", "request.expected.scope.incarnation",
		"request.expected.authority.epoch", "request.expected.authority.configuration_id",
		"request.expected.authority.certificate_sha256", "request.expected.authority.tls_leaf_sha256",
		"survivor.member_id", "survivor.incarnation", "source_sequence"); err != nil {
		return DrainRecord{}, false, err
	}
	if !record.valid(record.Request.Expected.Scope, record.Request.Expected.Authority) {
		return DrainRecord{}, false, ErrStaleBinding
	}
	return record, true, nil
}

member_lock.text:
func (s *FileStore) locked(action func() error) error {
	lock, err := os.OpenFile(s.path+".lock", os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		return err
	}
	defer lock.Close()
	info, err := lock.Stat()
	if err != nil {
		return err
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.Mode().IsRegular() || stat.Nlink != 1 || stat.Uid != uint32(os.Geteuid()) || info.Mode().Perm() != 0o600 {
		return errors.New("unsafe member drain lock")
	}
	if err := unix.Flock(int(lock.Fd()), unix.LOCK_EX); err != nil {
		return fmt.Errorf("lock member drain: %w", err)
	}
	defer unix.Flock(int(lock.Fd()), unix.LOCK_UN)
	return action()
}

drain.text:
func (c *Client) Drain(ctx context.Context, survivor Survivor, operationID string, store DrainStore) (DrainEnvelope, error) {
	if store == nil {
		return DrainEnvelope{}, errors.New("member drain has no durable store")
	}
	record, found, err := store.Load()
	if err != nil {
		return DrainEnvelope{}, err
	}
	if found {
		if !record.valid(c.scope, c.authority) || record.Request.OperationID != operationID || record.Survivor != survivor {
			return DrainEnvelope{}, ErrOperationConflict
		}
	} else {
		status, err := c.Status(ctx)
		if err != nil {
			return DrainEnvelope{}, err
		}
		proof, err := c.ServingProof(ctx, status, survivor)
		if err != nil {
			return DrainEnvelope{}, err
		}
		if _, err := c.PrepareDrain(status, proof, survivor, operationID, store); err != nil {
			return DrainEnvelope{}, err
		}
	}
	return c.ReconcileDrain(ctx, store)
}

prepare_drain.text:
func (c *Client) PrepareDrain(status Status, proof ServingProof, survivor Survivor, operationID string, store DrainStore) (DrainRecord, error) {
	if store == nil || !status.verified || !proof.verified || !entityid.Valid(operationID) || !survivor.valid() ||
		status.Process != proof.Process || status.Scope != proof.Scope || status.Authority != proof.Authority ||
		status.Scope != c.scope || status.Authority != c.authority || status.ReceiverOnly || !status.Serving ||
		proof.Replication.PeerMemberID != survivor.MemberID || proof.Replication.PeerIncarnation != survivor.Incarnation ||
		proof.Replication.PeerAppliedSequence < proof.Replication.LocalSourceSequence ||
		proof.Replication.PeerDurableSequence < proof.Replication.PeerAppliedSequence ||
		proof.Object.LocalSourceSequence != proof.Replication.LocalSourceSequence {
		return DrainRecord{}, ErrNotServing
	}
	challenge, err := nonce()
	if err != nil {
		return DrainRecord{}, err
	}
	record := DrainRecord{
		Request: DrainRequest{
			SchemaVersion: 1, OperationID: operationID, Nonce: challenge,
			Expected: Identity{Process: status.Process, Scope: c.scope, Authority: c.authority},
		},
		Survivor: survivor, SourceSequence: proof.Replication.LocalSourceSequence,
	}
	if err := store.Create(record); err != nil {
		return DrainRecord{}, fmt.Errorf("persist member drain request: %w", err)
	}
	return record, nil
}

reconcile_drain.text:
func (c *Client) ReconcileDrain(ctx context.Context, store DrainStore) (DrainEnvelope, error) {
	if store == nil {
		return DrainEnvelope{}, errors.New("member drain has no durable store")
	}
	record, found, err := store.Load()
	if err != nil {
		return DrainEnvelope{}, err
	}
	if !found || !record.valid(c.scope, c.authority) {
		return DrainEnvelope{}, ErrStaleBinding
	}
	status, err := c.Status(ctx)
	if err != nil {
		return DrainEnvelope{}, err
	}
	observation, code, err := c.drainStatus(ctx, record, status)
	if err != nil {
		return DrainEnvelope{}, errors.Join(ErrOutcomeUnknown, err)
	}
	if code != http.StatusNotFound {
		return observation, nil
	}
	if status.Process != record.Request.Expected.Process {
		return DrainEnvelope{}, ErrOutcomeUnknown
	}
	body, err := encodeRequest(record.Request)
	if err != nil {
		return DrainEnvelope{}, err
	}
	code, response, observed, err := c.exchange(ctx, http.MethodPost, "/v1/member/drain", body)
	if err != nil {
		return DrainEnvelope{}, errors.Join(ErrOutcomeUnknown, err)
	}
	if observed.ProtocolPID() != status.Process.PID {
		return DrainEnvelope{}, ErrStaleBinding
	}
	switch code {
	case http.StatusOK, http.StatusAccepted:
		return validateDrainEnvelope(response, code, record.Request.Nonce, status, record)
	case http.StatusConflict:
		return DrainEnvelope{}, ErrOperationConflict
	case http.StatusPreconditionFailed:
		// A process switch or an uncertain earlier POST can race the 404. Poll
		// again before classifying; never construct a new request in this path.
		current, statusErr := c.Status(ctx)
		if statusErr != nil {
			return DrainEnvelope{}, errors.Join(ErrOutcomeUnknown, statusErr)
		}
		observation, pollCode, pollErr := c.drainStatus(ctx, record, current)
		if pollErr == nil && pollCode != http.StatusNotFound {
			return observation, nil
		}
		return DrainEnvelope{}, ErrStaleBinding
	default:
		return DrainEnvelope{}, fmt.Errorf("member drain HTTP %d: %w", code, ErrOutcomeUnknown)
	}
}

drain_status.text:
func (c *Client) drainStatus(ctx context.Context, record DrainRecord, current Status) (DrainEnvelope, int, error) {
	challenge, err := nonce()
	if err != nil {
		return DrainEnvelope{}, 0, err
	}
	path := "/v1/member/drain-status?operation_id=" + record.Request.OperationID + "&nonce=" + challenge
	code, body, process, err := c.exchange(ctx, http.MethodGet, path, nil)
	if err != nil {
		return DrainEnvelope{}, 0, err
	}
	if process.ProtocolPID() != current.Process.PID {
		return DrainEnvelope{}, 0, ErrStaleBinding
	}
	if code == http.StatusNotFound {
		return DrainEnvelope{}, code, nil
	}
	if code != http.StatusOK && code != http.StatusAccepted {
		return DrainEnvelope{}, code, fmt.Errorf("member drain status HTTP %d", code)
	}
	observation, err := validateDrainEnvelope(body, code, challenge, current, record)
	return observation, code, err
}

drain_validate.text:
func validateDrainEnvelope(body []byte, code int, challenge string, current Status, record DrainRecord) (DrainEnvelope, error) {
	var envelope DrainEnvelope
	if err := decodeRequired(body, &envelope, drainEnvelopePaths...); err != nil {
		return DrainEnvelope{}, err
	}
	if err := requirePresent(body, "receipt_sha256", "receipt"); err != nil {
		return DrainEnvelope{}, err
	}
	if envelope.SchemaVersion != 1 || envelope.Nonce != challenge || envelope.OperationID != record.Request.OperationID ||
		envelope.Process != current.Process {
		return DrainEnvelope{}, ErrStaleBinding
	}
	if envelope.State == "pending" && code == http.StatusAccepted && envelope.Receipt == nil && envelope.ReceiptSHA256 == nil {
		return envelope, nil
	}
	if envelope.State != "complete" || code != http.StatusOK || envelope.Receipt == nil || envelope.ReceiptSHA256 == nil ||
		!lowerHex(*envelope.ReceiptSHA256, 64) {
		return DrainEnvelope{}, errors.New("inconsistent member drain state")
	}
	var required map[string]any
	if err := json.Unmarshal(body, &required); err != nil {
		return DrainEnvelope{}, err
	}
	if err := requireReceiptFields(required); err != nil {
		return DrainEnvelope{}, err
	}
	receipt := envelope.Receipt
	digest, err := receipt.digest()
	if err != nil || digest != *envelope.ReceiptSHA256 || receipt.SchemaVersion != 1 ||
		receipt.OperationID != record.Request.OperationID || receipt.RequestNonce != record.Request.Nonce ||
		receipt.RequestedProcess != record.Request.Expected.Process || !receipt.DrainedProcess.valid() ||
		receipt.Scope != record.Request.Expected.Scope || receipt.Authority != record.Request.Expected.Authority ||
		receipt.LocalSourceOrigin != (Origin{MemberID: receipt.Scope.MemberID, Incarnation: receipt.Scope.Incarnation}) ||
		receipt.LocalSourceDurableSequence < record.SourceSequence ||
		receipt.ArchivedSourceSequence != receipt.LocalSourceDurableSequence ||
		!lowerHex(receipt.ObjectRootSHA256, 64) ||
		receipt.Peer.Origin != (Origin{MemberID: record.Survivor.MemberID, Incarnation: record.Survivor.Incarnation}) ||
		receipt.Peer.DurableSequence < receipt.LocalSourceDurableSequence ||
		receipt.Peer.AppliedSequence < receipt.LocalSourceDurableSequence ||
		receipt.Peer.AppliedSequence > receipt.Peer.DurableSequence ||
		receipt.Peer.LocalInboxAppliedSequence > receipt.Peer.LocalInboxDurableSequence ||
		!receipt.ReplicationQuiesced {
		return DrainEnvelope{}, errors.New("member drain receipt violates signed survivor or root frontier")
	}
	envelope.verified = true
	return envelope, nil
}

retain_complete.text:
func (s *FileStore) RetainComplete(envelope DrainEnvelope) error {
	if !envelope.verified {
		return ErrOutcomeUnknown
	}
	return s.locked(func() error {
		record, found, err := s.loadUnlocked()
		if err != nil || !found {
			return errors.Join(ErrStaleBinding, err)
		}
		wire, err := json.Marshal(envelope)
		if err != nil || len(wire) > maxEvidenceBytes {
			return errors.Join(ErrOutcomeUnknown, err)
		}
		if _, err := validateDrainEnvelope(wire, http.StatusOK, envelope.Nonce, Status{Process: envelope.Process}, record); err != nil {
			return err
		}
		if current, found, err := s.readCompleteUnlocked(record); err != nil {
			return err
		} else if found {
			if current.ReceiptSHA256 == nil || envelope.ReceiptSHA256 == nil || *current.ReceiptSHA256 != *envelope.ReceiptSHA256 {
				return ErrOperationConflict
			}
			return nil
		}
		file, err := os.CreateTemp(filepath.Dir(s.path), ".member-complete-*")
		if err != nil {
			return err
		}
		defer os.Remove(file.Name())
		if err := file.Chmod(0o600); err != nil {
			file.Close()
			return err
		}
		if _, err := file.Write(wire); err != nil {
			file.Close()
			return err
		}
		if err := file.Sync(); err != nil {
			file.Close()
			return err
		}
		if err := file.Close(); err != nil {
			return err
		}
		if err := os.Rename(file.Name(), s.path+".complete"); err != nil {
			return err
		}
		directory, err := os.Open(filepath.Dir(s.path))
		if err != nil {
			return err
		}
		defer directory.Close()
		return directory.Sync()
	})
}

start_peer.text:
func startDrainPeer(t *testing.T, binding peerBinding) (*memberstatus.Client, string) {
	t.Helper()
	directory, err := os.MkdirTemp("", "ts-execution-peer-")
	if err != nil {
		t.Fatal(err)
	}
	uid, gid := os.Getuid(), os.Getgid()
	if uid == 0 {
		uid, gid = 65534, 65534
	}
	if err := os.Chown(directory, uid, gid); err != nil {
		t.Fatal(err)
	}
	control := filepath.Join(directory, "control")
	if err := os.Mkdir(control, 0o730); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(control, 0o730); err != nil {
		t.Fatal(err)
	}
	var ownershipError error
	if os.Getuid() == 0 {
		ownershipError = os.Chown(control, 0, gid)
	} else {
		ownershipError = exec.Command("sudo", "-n", "chown", "0:"+strconv.Itoa(gid), control).Run()
	}
	if err := ownershipError; err != nil {
		t.Fatalf("root-owned control fixture requires passwordless sudo: %v", err)
	}
	t.Cleanup(func() {
		_ = os.Remove(filepath.Join(control, "member.sock"))
		_ = os.Remove(control)
		_ = os.RemoveAll(directory)
	})
	raw, err := json.Marshal(binding)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(directory, "binding"), raw, 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(directory, "mode"), []byte("pending"), 0o644); err != nil {
		t.Fatal(err)
	}
	executable, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	contents, err := os.ReadFile(executable)
	if err != nil {
		t.Fatal(err)
	}
	binary := filepath.Join(directory, "fixture.test")
	if err := os.WriteFile(binary, contents, 0o755); err != nil {
		t.Fatal(err)
	}
	child := exec.Command(binary, "-test.run=^TestDrainProtocolPeer$")
	if os.Getuid() == 0 {
		child.SysProcAttr = &syscall.SysProcAttr{Credential: &syscall.Credential{Uid: uint32(uid), Gid: uint32(gid)}}
	}
	child.Env = append(os.Environ(), "TS_EXECUTION_DRAIN_PEER="+directory)
	child.Stdout = os.Stderr
	child.Stderr = os.Stderr
	if err := child.Start(); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = child.Process.Kill(); _ = child.Wait() })
	socket := filepath.Join(control, "member.sock")
	for deadline := time.Now().Add(5 * time.Second); ; {
		if _, err := os.Stat(socket); err == nil {
			break
		}
		if time.Now().After(deadline) {
			t.Fatal("member protocol peer socket missing")
		}
		time.Sleep(5 * time.Millisecond)
	}
	observe := func(context.Context) (memberstatus.ProcessObservation, error) {
		proc := "/proc/" + strconv.Itoa(child.Process.Pid)
		raw, err := os.ReadFile(proc + "/stat")
		if err != nil {
			return memberstatus.ProcessObservation{}, err
		}
		_, suffix, ok := strings.CutLast(string(raw), ") ")
		fields := strings.Fields(suffix)
		if !ok || len(fields) < 20 {
			return memberstatus.ProcessObservation{}, errors.New("invalid process stat")
		}
		cgroup, err := os.ReadFile(proc + "/cgroup")
		if err != nil {
			return memberstatus.ProcessObservation{}, err
		}
		return memberstatus.ProcessObservation{PID: child.Process.Pid, UID: uint32(uid), GID: uint32(gid), KernelStart: fields[19], Cgroup: string(cgroup)}, nil
	}
	client, err := memberstatus.NewClient(socket, binding.Scope, binding.Authority, observe)
	if err != nil {
		t.Fatal(err)
	}
	return client, directory
}

backup_peer.text:
func serveBackupPeer(t *testing.T, directory string) {
	t.Helper()
	listener, err := net.Listen("unix", filepath.Join(directory, "control", "member.sock"))
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(listener.Addr().String(), 0o602); err != nil {
		t.Fatal(err)
	}
	if err := http.Serve(listener, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, err := io.ReadAll(r.Body)
		if err != nil {
			panic(err)
		}
		if err := os.WriteFile(filepath.Join(directory, "last-request"), append([]byte(r.Method+" "+r.URL.Path+"\n"), body...), 0o600); err != nil {
			panic(err)
		}
		var reply []byte
		switch r.URL.Path {
		case "/v1/backup/prepare":
			reply = []byte(backupPeerCut)
		case "/v1/backup/release":
			reply = []byte(`{"version":1,"state":"released"}`)
		case "/v1/backup/cut-proof":
			reply = []byte(`{"version":1,"state":"accepted"}`)
		case "/v1/backup/barrier":
			digest := sha256.Sum256(body)
			reply, err = json.Marshal(struct {
				Version uint64 `json:"version"`
				SHA256  string `json:"barrier_sha256"`
			}{1, hex.EncodeToString(digest[:])})
		case "/v1/backup/complete":
			reply = []byte(backupPeerReceipt)
		case "/v1/backup/operations/" + backupPeerOperation:
			state, err := os.ReadFile(filepath.Join(directory, "mode"))
			if err != nil {
				panic(err)
			}
			reply, err = json.Marshal(memberstatus.BackupOperationStatus{Version: 1, OperationID: backupPeerOperation, State: string(state), Ordinal: 7, Attempt: 2, PublishedHeadReceipt: backupPeerReceipt})
		default:
			http.Error(w, "unexpected path", http.StatusNotFound)
			return
		}
		if err != nil {
			panic(err)
		}
		if r.Method == http.MethodPost {
			if err := os.WriteFile(filepath.Join(directory, "last-mutation"), append([]byte(r.URL.Path+"\n"), body...), 0o600); err != nil {
				panic(err)
			}
		}
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("Content-Length", strconv.Itoa(len(reply)))
		_, _ = w.Write(reply)
	})); err != nil {
		t.Fatal(err)
	}
}

drain_peer.text:
func TestDrainProtocolPeer(t *testing.T) {
	directory := os.Getenv("TS_EXECUTION_DRAIN_PEER")
	if directory == "" {
		return
	}
	raw, err := os.ReadFile(filepath.Join(directory, "binding"))
	if err != nil {
		t.Fatal(err)
	}
	var binding peerBinding
	if err := json.Unmarshal(raw, &binding); err != nil {
		t.Fatal(err)
	}
	if binding.Backup {
		serveBackupPeer(t, directory)
		return
	}
	listener, err := net.Listen("unix", filepath.Join(directory, "control", "member.sock"))
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(listener.Addr().String(), 0o602); err != nil {
		t.Fatal(err)
	}
	process := memberstatus.Process{PID: os.Getpid(), StartNonce: strings.Repeat("1", 32)}
	err = http.Serve(listener, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		challenge := r.URL.Query().Get("nonce")
		code := http.StatusOK
		var reply any
		switch r.URL.Path {
		case "/v1/member/status":
			reply = memberstatus.Status{SchemaVersion: 2, Nonce: challenge, Process: process, Scope: binding.Scope, Authority: binding.Authority, Local: memberstatus.Local{StorageRecovered: true, ReplicationListenerReady: true, Healthy: true, Ready: true}, Serving: true, Capabilities: memberstatus.Capabilities{ServingProof: true, DurableDrain: true}}
		case "/v1/member/serving-proof":
			reply = memberstatus.ServingProof{SchemaVersion: 1, Nonce: challenge, Process: process, Scope: binding.Scope, Authority: binding.Authority, Serving: true, Listeners: memberstatus.Listeners{Client: true, Replication: true}, Object: memberstatus.ObjectProof{RootSHA256: strings.Repeat("5", 64), TargetSHA256: strings.Repeat("6", 64), InboxArchiveSHA256AtRecovery: strings.Repeat("8", 64), LocalSourceSequence: 12, RemoteInboxDurableSequence: 9, RemoteAppliedSequence: 9}, Replication: memberstatus.ReplicationProof{LocalSourceSequence: 12, PeerMemberID: binding.Survivor.MemberID, PeerIncarnation: binding.Survivor.Incarnation, CurrentAuthenticated: true, PeerDurableSequence: 12, PeerAppliedSequence: 12, LocalInboxDurableSequence: 9, LocalInboxAppliedSequence: 9}}
		case "/v1/member/drain", "/v1/member/drain-status":
			path := filepath.Join(directory, "peer-request")
			var request memberstatus.DrainRequest
			if r.Method == http.MethodPost {
				body, err := io.ReadAll(r.Body)
				if err != nil {
					panic(err)
				}
				if err := os.WriteFile(path, body, 0o600); err != nil {
					panic(err)
				}
			}
			body, err := os.ReadFile(path)
			if errors.Is(err, os.ErrNotExist) {
				code = http.StatusNotFound
				reply = map[string]string{"state": "absent"}
				break
			}
			if err != nil {
				panic(err)
			}
			if err := json.Unmarshal(body, &request); err != nil {
				panic(err)
			}
			if r.Method == http.MethodPost {
				challenge = request.Nonce
			}
			mode, err := os.ReadFile(filepath.Join(directory, "mode"))
			if err != nil {
				panic(err)
			}
			envelope := memberstatus.DrainEnvelope{SchemaVersion: 1, Nonce: challenge, Process: process, OperationID: request.OperationID, State: "pending"}
			if string(mode) == "pending" {
				code = http.StatusAccepted
				reply = envelope
				break
			}
			applied := uint64(15)
			if string(mode) == "lag" {
				applied = 14
			}
			receipt := memberstatus.DrainReceipt{SchemaVersion: 1, OperationID: request.OperationID, RequestNonce: request.Nonce, RequestedProcess: request.Expected.Process, DrainedProcess: process, Scope: binding.Scope, Authority: binding.Authority, LocalSourceOrigin: memberstatus.Origin{MemberID: binding.Scope.MemberID, Incarnation: binding.Scope.Incarnation}, LocalSourceDurableSequence: 15, ArchivedSourceSequence: 15, ObjectRootSHA256: strings.Repeat("5", 64), Peer: memberstatus.DrainPeer{Origin: memberstatus.Origin{MemberID: binding.Survivor.MemberID, Incarnation: binding.Survivor.Incarnation}, DurableSequence: 15, AppliedSequence: applied, LocalInboxDurableSequence: 9, LocalInboxAppliedSequence: 9}, ReplicationQuiesced: true}
			canonical, err := json.Marshal(receipt)
			if err != nil {
				panic(err)
			}
			sum := sha256.Sum256(canonical)
			digest := hex.EncodeToString(sum[:])
			envelope.State = "complete"
			envelope.Receipt = &receipt
			envelope.ReceiptSHA256 = &digest
			reply = envelope
		default:
			code = http.StatusNotFound
			reply = map[string]string{"state": "absent"}
		}
		body, err := json.Marshal(reply)
		if err != nil {
			panic(err)
		}
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("Content-Length", strconv.Itoa(len(body)))
		w.WriteHeader(code)
		_, _ = w.Write(body)
	}))
	if err != nil {
		t.Fatal(err)
	}
}

oci_init.text:
func (f *fleet) InspectVolumeInitialization(ctx context.Context, pins VolumeInitializationPins) (VolumeInitializationProof, error) {
	if pins.InstanceID == "" || pins.HostCreateKey == "" || pins.VolumeID == "" || pins.AttachmentID == "" ||
		pins.DatabaseID == "" || pins.PartitionID == "" || pins.AttachmentETag == "" || !validDevicePath(pins.Device) ||
		pins.FileSystemUUID == "" || pins.FileSystemType != "ext4" && pins.FileSystemType != "xfs" {
		return VolumeInitializationProof{}, errors.New("volume initialization pins are incomplete")
	}
	epoch, err := f.currentEpoch()
	if err != nil {
		return VolumeInitializationProof{}, err
	}
	release, err := f.beginActiveWorkloadEffect(ctx, epoch, pins.DatabaseID, pins.PartitionID)
	if err != nil {
		return VolumeInitializationProof{}, err
	}
	defer release()
	instances, err := f.Observe(ctx)
	if err != nil {
		return VolumeInitializationProof{}, err
	}
	var selected *Instance
	for i := range instances {
		if instances[i].ID == pins.InstanceID {
			selected = &instances[i]
			break
		}
	}
	if selected == nil || selected.CreateKey != pins.HostCreateKey || selected.State != "RUNNING" ||
		selected.BootDescriptorSHA256 == "" {
		return VolumeInitializationProof{}, fmt.Errorf("%w: signed host is not an owned running instance", ErrForeignResource)
	}
	matched := false
	for _, attachment := range selected.Attachments {
		if attachment.ID == pins.AttachmentID && attachment.VolumeID == pins.VolumeID &&
			attachment.InstanceID == pins.InstanceID && attachment.ETag == pins.AttachmentETag &&
			attachment.Device == pins.Device && attachment.State == "ATTACHED" &&
			!attachment.IsReadOnly && !attachment.IsShareable && attachment.IsPvEncryptionInTransitEnabled {
			matched = true
		}
	}
	if !matched {
		return VolumeInitializationProof{}, fmt.Errorf("%w: signed attachment is not current on the owned instance", ErrForeignResource)
	}
	volume, err := f.ownedVolume(ctx, pins.VolumeID)
	if err != nil {
		return VolumeInitializationProof{}, err
	}
	if volume.LifecycleState != "AVAILABLE" || volume.CompartmentID != f.config.CompartmentID ||
		volume.AvailabilityDomain != f.config.AvailabilityDomain {
		return VolumeInitializationProof{}, fmt.Errorf("%w: retained volume is not the available regional resource", ErrForeignResource)
	}
	attachments, err := f.findVolumeAttachments(ctx, pins.VolumeID)
	if err != nil {
		return VolumeInitializationProof{}, err
	}
	if len(attachments) != 1 || attachments[0].ID != pins.AttachmentID || attachments[0].InstanceID != pins.InstanceID {
		// A reattached volume keeps the DETACHED attachment of its fenced
		// host. Only a recorded mount-existing permit for exactly this
		// attachment admits that history, and it never grants a format.
		mountOnly, err := f.mountExistingPermitted(ctx, pins, attachments)
		if err != nil {
			return VolumeInitializationProof{}, err
		}
		if !mountOnly {
			return VolumeInitializationProof{}, fmt.Errorf("%w: volume has another attachment history", ErrForeignResource)
		}
		return VolumeInitializationProof{BootDescriptorSHA256: selected.BootDescriptorSHA256}, nil
	}
	operations, err := f.journal.ListOperations(ctx)
	if err != nil {
		return VolumeInitializationProof{}, err
	}
	creates, attaches, otherAttachmentEffects := 0, 0, 0
	for _, operation := range operations {
		intent, result := operation.Intent, operation.Result
		if intent.Region != f.config.Region || intent.Generation != f.config.Generation || intent.Owner != f.config.Owner ||
			intent.VolumeID != pins.VolumeID && result.ResourceID != pins.VolumeID {
			continue
		}
		switch intent.Action {
		case actionVolumeCreate:
			if result.ResourceID == pins.VolumeID && !result.Unknown && !result.RecordedAt.IsZero() {
				creates++
			}
		case actionVolumeAttach:
			if intent.ResourceID == pins.InstanceID && intent.VolumeID == pins.VolumeID && intent.Device == pins.Device &&
				result.ResourceID == pins.AttachmentID && result.ETag == pins.AttachmentETag &&
				!result.Unknown && !result.RecordedAt.IsZero() {
				attaches++
			} else {
				otherAttachmentEffects++
			}
		case actionVolumeDetach:
			otherAttachmentEffects++
		}
	}
	proof := VolumeInitializationProof{BootDescriptorSHA256: selected.BootDescriptorSHA256}
	// The pin validation above admits only ext4 and xfs, both of which the
	// host initializer can format.
	if creates != 1 || attaches != 1 || otherAttachmentEffects != 0 {
		return proof, nil
	}
	if err := f.guard(ctx, epoch); err != nil {
		return VolumeInitializationProof{}, err
	}
	store, ok := f.journal.(VolumeFormatPermitStore)
	if !ok {
		return VolumeInitializationProof{}, errors.New("OCI journal cannot atomically consume volume format authority")
	}
	proof.AllowFormat, err = store.ClaimVolumeFormatPermit(ctx, VolumeFormatPermitRecord{
		Region: f.config.Region, Generation: f.config.Generation, Owner: f.config.Owner,
		DatabaseID: pins.DatabaseID, PartitionID: pins.PartitionID,
		InstanceID: pins.InstanceID, HostCreateKey: pins.HostCreateKey,
		VolumeID: pins.VolumeID, AttachmentID: pins.AttachmentID,
		AttachmentETag: pins.AttachmentETag, Device: pins.Device,
		FileSystemUUID: pins.FileSystemUUID, FileSystemType: pins.FileSystemType,
		BootDescriptorSHA256: selected.BootDescriptorSHA256,
	})
	if err != nil {
		return VolumeInitializationProof{}, err
	}
	return proof, nil
}

oci_fleet.text:
func NewFleet(
	config RegionConfig,
	intent RegionIntent,
	provider Provider,
	journal Journal,
	fencer authority.Fencer,
	drainRequester DrainRequester,
	writerStop WriterStopVerifier,
) (Fleet, error) {
	return newFleet(config, intent, provider, journal, fencer, drainRequester, writerStop, nil)
}

// NewFleetWithImageVerifier is the injected qualification seam for a verified
// image evidence source. A nil verifier is allowed for compatibility, but
// retained-volume creation and attachment will hold until one is configured.
func NewFleetWithImageVerifier(
	config RegionConfig,
	intent RegionIntent,
	provider Provider,
	journal Journal,
	fencer authority.Fencer,
	drainRequester DrainRequester,
	writerStop WriterStopVerifier,
	imageVerifier ImageQualificationVerifier,
) (Fleet, error) {
	return newFleet(config, intent, provider, journal, fencer, drainRequester, writerStop, imageVerifier)
}

func newFleet(
	config RegionConfig,
	intent RegionIntent,
	provider Provider,
	journal Journal,
	fencer authority.Fencer,
	drainRequester DrainRequester,
	writerStop WriterStopVerifier,
	imageVerifier ImageQualificationVerifier,
) (Fleet, error) {
	if err := config.Validate(intent); err != nil {
		return nil, err
	}
	if provider == nil || journal == nil || fencer == nil {
		return nil, errors.New("OCI fleet requires a provider, durable journal, and authority fencer")
	}
	return &fleet{
		config: config, provider: provider, journal: journal, fencer: fencer,
		drainRequester: drainRequester, writerStop: writerStop, imageVerifier: imageVerifier, now: time.Now,
		attachmentSettle: attachmentSettleTimeout,
	}, nil
}

oci_journal.text:
func OpenJournal(ctx context.Context, js jetstream.JetStream, replicas int) (*KVJournal, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("OCI journal requires JetStream and one to five replicas")
	}
	kv, err := js.CreateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket:       journalBucket,
		Description:  "Durable OCI mutation intent and resource ownership",
		MaxValueSize: journalMaxValueSize,
		History:      5,
		Storage:      jetstream.FileStorage,
		Replicas:     replicas,
		Compression:  true,
	})
	if err != nil {
		if !errors.Is(err, jetstream.ErrBucketExists) {
			return nil, fmt.Errorf("create OCI journal bucket: %w", err)
		}
		kv, err = js.KeyValue(ctx, journalBucket)
		if err != nil {
			return nil, fmt.Errorf("open existing OCI journal bucket: %w", err)
		}
		status, statusErr := kv.Status(ctx)
		if statusErr != nil {
			return nil, fmt.Errorf("inspect OCI journal bucket: %w", statusErr)
		}
		config := status.Config()
		if config.Replicas != replicas || config.Storage != jetstream.FileStorage || config.TTL != 0 || config.History < 2 || config.MaxValueSize > journalMaxValueSize {
			return nil, errors.New("existing OCI journal bucket has incompatible durability limits")
		}
	}
	return NewKVJournal(kv)
}

oci_journal_wrap.text:
func NewKVJournal(kv jetstream.KeyValue) (*KVJournal, error) {
	if kv == nil {
		return nil, errors.New("OCI journal KV bucket is required")
	}
	return &KVJournal{kv: kv}, nil
}

oci_observe.text:
func (f *fleet) Observe(ctx context.Context) ([]Instance, error) {
	return f.observe(ctx, nil)
}

oci_observe_impl.text:
func (f *fleet) observe(ctx context.Context, selectInstance func(id, node string) bool) ([]Instance, error) {
	cloudInstances, err := f.provider.ListInstances(ctx, f.config.CompartmentID)
	if err != nil {
		return nil, err
	}
	if len(cloudInstances) > maxFleetInstances {
		return nil, errors.New("OCI member host list exceeds its safety bound")
	}
	// A complete sweep also counts the fleet by lifecycle state for the
	// dashboard; the tally never changes what the sweep returns.
	var tally *inventoryTally
	if selectInstance == nil {
		tally = newInventoryTally()
		ctx = withInventoryTally(ctx, tally)
	}
	instances := make([]Instance, 0, len(cloudInstances))
	for _, listed := range cloudInstances {
		tags := listed.FreeformTags
		if tags[tagManagedBy] != managedByValue || tags[tagOwner] != f.config.Owner {
			continue
		}
		createKey := tags[tagCreateKey]
		if tags[tagRegion] != string(f.config.Region) || tags[tagGeneration] != fmt.Sprint(f.config.Generation) ||
			tags[tagResource] != resourceMemberHost || !validCreateKey(createKey) || tags[tagHostNode] != hostNode(f.config, createKey) {
			slog.WarnContext(ctx, "withholding OCI instance with out-of-scope identity tags", "instance_id", listed.ID, "region", f.config.Region)
			continue
		}
		tally.instance(listed.LifecycleState)
		if selectInstance != nil && !selectInstance(listed.ID, tags[tagHostNode]) {
			continue
		}
		cloud, identity, err := f.reobserveInstance(ctx, listed.ID)
		if err != nil {
			if errors.Is(err, ErrForeignResource) {
				slog.WarnContext(ctx, "withholding OCI instance without a verified regional identity", "instance_id", listed.ID, "region", f.config.Region)
				continue
			}
			return nil, err
		}
		owned, err := f.journal.IsOwnedInstance(ctx, identity)
		if err != nil {
			return nil, fmt.Errorf("read OCI host ownership journal: %w", err)
		}
		if !owned {
			slog.WarnContext(ctx, "withholding OCI instance without durable controller ownership", "instance_id", cloud.ID, "region", f.config.Region, "create_key", identity.CreateKey)
			continue
		}
		profileIntent, found, err := f.journal.GetOperation(ctx, OperationScope{
			Action: actionLaunch, Key: identity.CreateKey, Region: identity.Region,
			Generation: identity.Generation, Owner: identity.Owner,
		})
		if err != nil {
			return nil, fmt.Errorf("read OCI host placement profile: %w", err)
		}
		if !found || profileIntent.Shape != f.config.Shape || !cloudMatchesLaunchBinding(cloud, profileIntent) {
			slog.WarnContext(ctx, "withholding OCI instance that does not match its signed placement compute profile", "instance_id", cloud.ID, "region", f.config.Region, "create_key", identity.CreateKey)
			continue
		}
		instance, err := f.instanceFromCloud(ctx, cloud, identity, profileIntent)
		if err != nil {
			if errors.Is(err, ErrAttachmentRecoveryHold) || errors.Is(err, ErrForeignResource) ||
				errors.Is(err, ErrRetainedVolumeUnknown) {
				slog.WarnContext(ctx, "withholding OCI instance with an unverified retained volume attachment", "instance_id", cloud.ID, "region", f.config.Region, "error", err)
				continue
			}
			return nil, err
		}
		instances = append(instances, instance)
	}
	if tally != nil {
		publishInventory(f.config.Region, tally, f.now())
	}
	return instances, nil
}

