terminal_required.text:
func (r *Runtime) requireNoTerminalIntent(ctx context.Context, databaseID, partitionID string) error {
	_, err := r.ReadTerminalIntent(ctx, databaseID, partitionID)
	if errors.Is(err, ErrNotFound) {
		return nil
	}
	if err == nil {
		return ErrFenced
	}
	return err
}

terminal_read.text:
func (r *Runtime) ReadTerminalIntent(ctx context.Context, databaseID, partitionID string) (LogEntry, error) {
	subjectKey, err := placementIntentSubjectKey(databaseID, partitionID)
	if err != nil {
		return LogEntry{}, err
	}
	if r == nil {
		return LogEntry{}, ErrFenced
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	entry, err := readMutation(ctx, r.readStream, r.config.Scope, MutationTerminalIntent, subjectKey)
	if err != nil {
		return LogEntry{}, err
	}
	intent, err := decodeTerminalIntent(entry.Payload)
	if err != nil || intent.Cell != r.config.Scope || intent.DatabaseID != databaseID ||
		intent.PartitionID != partitionID || intent.OperationID != entry.OperationID {
		return LogEntry{}, errors.New("terminal control log identity is invalid")
	}
	return entry, nil
}

mutation_read.text:
func readMutation(ctx context.Context, stream jetstream.Stream, scope string, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	subject := mutationSubject(scope, kind, subjectKey)
	entry, err := stream.GetLastMsgForSubject(ctx, subject)
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return LogEntry{}, ErrNotFound
	}
	if err != nil {
		return LogEntry{}, err
	}
	record, err := decodeControlRecord(entry.Data)
	if err != nil || record.Scope != scope || record.Kind != kind || record.SubjectKey != subjectKey || record.Epoch == 0 {
		return LogEntry{}, errors.New("host control log entry is invalid")
	}
	return LogEntry{
		Kind: record.Kind, SubjectKey: record.SubjectKey, OperationID: record.OperationID,
		Epoch: record.Epoch, Sequence: entry.Sequence, CreatedAt: entry.Time, Payload: bytes.Clone(record.Payload),
	}, nil
}

stateful_current.text:
func VerifyStatefulCurrent(ctx context.Context, bundle release.ContainerBundle, roots trust.Keyring,
	target release.ContainerTarget, data RetainedData, cpu CPUProfile, now, until time.Time,
	evidence func(context.Context, string) (io.ReadCloser, error), allocations release.SequenceLocation,
) (VerifiedStateful, error) {
	if ctx == nil || ctx.Err() != nil || target.Role != "terrabase" || !retainedDataValid(data) || !cpu.valid() ||
		cpu.Architecture != target.Architecture || now.IsZero() || !until.After(now) || evidence == nil {
		return VerifiedStateful{}, fmt.Errorf("%w: stateful qualification scope", release.ErrProductionQualification)
	}
	container, err := release.VerifyContainerCurrent(ctx, bundle, roots, target, now, until, evidence, allocations)
	if err != nil {
		return VerifiedStateful{}, err
	}
	claim := container.Claim()
	_, imageDigest, _ := strings.Cut(claim.Image, "@sha256:")
	expected := release.ProductionExpectation{SourceRevision: claim.SourceRevision, ArtifactSHA256: imageDigest,
		QualificationSHA256: claim.QualificationSHA256, Cell: claim.Cell, Environment: claim.Environment,
		Runtime: release.ProductionRuntime, Architecture: claim.Architecture, Role: claim.Role}
	qualification, err := release.VerifyProductionCurrent(claim.Production.Qualification, claim.Production.Delegation, roots, expected, now)
	if err != nil {
		return VerifiedStateful{}, err
	}
	retained := qualification.Evidence[1]
	// The signed outer verifier fixes this index to workload-safety.
	wire, err := readStatefulEvidence(ctx, evidence, retained, trust.MaxPayloadBytes)
	if err != nil {
		return VerifiedStateful{}, err
	}
	var proof StatefulQualification
	if err := protocol.DecodeStrict(wire, &proof, trust.MaxPayloadBytes); err != nil {
		return VerifiedStateful{}, fmt.Errorf("%w: typed workload-safety evidence", release.ErrProductionQualification)
	}
	if proof.Schema != StatefulQualificationSchema || proof.CandidateSourceTreeSHA256 != claim.SourceTreeSHA256 ||
		proof.Data != data || proof.TargetCPU != cpu || !proof.SourceCPU.valid() ||
		proof.SourceCPU.Architecture != data.SourceArchitecture || proof.DiskFormatSHA256 != data.DiskFormatSHA256 {
		return VerifiedStateful{}, fmt.Errorf("%w: retained data, source, CPU or disk format differs", release.ErrProductionQualification)
	}
	expectedResult := proof.ResultData
	expectedResult.DiskFormatSHA256 = data.DiskFormatSHA256
	expectedResult.SourceArtifactSHA256 = data.SourceArtifactSHA256
	expectedResult.SourceTreeSHA256 = data.SourceTreeSHA256
	expectedResult.SourceArchitecture = data.SourceArchitecture
	if !retainedDataValid(proof.ResultData) || expectedResult != data || proof.ResultData.SourceArtifactSHA256 != imageDigest ||
		proof.ResultData.SourceTreeSHA256 != claim.SourceTreeSHA256 || proof.ResultData.SourceArchitecture != claim.Architecture {
		return VerifiedStateful{}, fmt.Errorf("%w: resulting retained data provenance differs", release.ErrProductionQualification)
	}
	if proof.ImageManifest.Gate != "image-manifest" || proof.ImageManifest.SHA256 != imageDigest ||
		proof.ImageConfig.Gate != "image-config" || proof.ImageManifest.CompletedAt.IsZero() || proof.ImageConfig.CompletedAt.IsZero() ||
		proof.ImageManifest.CompletedAt.After(retained.CompletedAt) || proof.ImageConfig.CompletedAt.After(retained.CompletedAt) {
		return VerifiedStateful{}, fmt.Errorf("%w: image config provenance", release.ErrProductionQualification)
	}
	manifestWire, err := readStatefulEvidence(ctx, evidence, proof.ImageManifest, trust.MaxPayloadBytes)
	if err != nil {
		return VerifiedStateful{}, err
	}
	configWire, err := readStatefulEvidence(ctx, evidence, proof.ImageConfig, trust.MaxPayloadBytes)
	if err != nil {
		return VerifiedStateful{}, err
	}
	var manifest ocispec.Manifest
	var imageConfig ocispec.Image
	if err := json.Unmarshal(manifestWire, &manifest); err != nil {
		return VerifiedStateful{}, err
	}
	if err := json.Unmarshal(configWire, &imageConfig); err != nil {
		return VerifiedStateful{}, err
	}
	if manifest.SchemaVersion != 2 || manifest.Config.Digest.String() != "sha256:"+proof.ImageConfig.SHA256 || manifest.Config.Size != proof.ImageConfig.Bytes ||
		imageConfig.Architecture != claim.Architecture || imageConfig.OS != "linux" || len(imageConfig.Config.Entrypoint) == 0 || len(imageConfig.Config.Cmd) != 0 {
		return VerifiedStateful{}, fmt.Errorf("%w: exact child image configuration", release.ErrProductionQualification)
	}
	gates := [...]string{"retained-restart", "restore", "replication-catchup", "durable-drain", "sigterm", "cpu-format-transition"}
	if len(proof.Scenarios) != len(gates) {
		return VerifiedStateful{}, fmt.Errorf("%w: required stateful scenarios", release.ErrProductionQualification)
	}
	total := retained.Bytes + proof.ImageManifest.Bytes + proof.ImageConfig.Bytes
	nativeSource := false
	if proof.SourceArtifact != nil {
		source := *proof.SourceArtifact
		if source.Gate != "native-source-artifact" || source.SHA256 != data.SourceArtifactSHA256 || source.CompletedAt.IsZero() || source.CompletedAt.After(retained.CompletedAt) || source.Bytes > release.MaxProductionEvidenceBytes-total {
			return VerifiedStateful{}, release.ErrProductionQualification
		}
		sourceWire, err := readStatefulEvidence(ctx, evidence, source, release.MaxProductionEvidenceBytes-total)
		if err != nil {
			return VerifiedStateful{}, err
		}
		binary, err := elf.NewFile(bytes.NewReader(sourceWire))
		if err != nil {
			return VerifiedStateful{}, fmt.Errorf("%w: native source ELF", release.ErrProductionQualification)
		}
		arch := ""
		switch binary.Machine {
		case elf.EM_X86_64:
			arch = "amd64"
		case elf.EM_AARCH64:
			arch = "arm64"
		}
		if arch == "" || arch != data.SourceArchitecture || binary.Class != elf.ELFCLASS64 || binary.Data != elf.ELFDATA2LSB {
			return VerifiedStateful{}, release.ErrProductionQualification
		}
		total += source.Bytes
		nativeSource = true
	}
	for index, gate := range gates {
		scenario := proof.Scenarios[index]
		if scenario.Gate != gate || scenario.CompletedAt.IsZero() || scenario.CompletedAt.After(retained.CompletedAt) ||
			scenario.Bytes <= 0 || scenario.Bytes > release.MaxProductionEvidenceBytes-total {
			return VerifiedStateful{}, fmt.Errorf("%w: %s scenario", release.ErrProductionQualification, gate)
		}
		total += scenario.Bytes
		if _, err := readStatefulEvidence(ctx, evidence, scenario, release.MaxProductionEvidenceBytes); err != nil {
			return VerifiedStateful{}, err
		}
	}
	return VerifiedStateful{container: container, data: data, result: proof.ResultData, cpu: cpu, digest: retained.SHA256, until: until, imageConfig: imageConfig, nativeSource: nativeSource}, nil
}

stateful_evidence.text:
func readStatefulEvidence(ctx context.Context, open func(context.Context, string) (io.ReadCloser, error),
	evidence release.ProductionGateEvidence, maximum int64,
) ([]byte, error) {
	if !digestValid(evidence.SHA256) || evidence.Bytes <= 0 || evidence.Bytes > maximum {
		return nil, release.ErrProductionQualification
	}
	reader, err := open(ctx, evidence.SHA256)
	if err != nil {
		return nil, err
	}
	if reader == nil {
		return nil, release.ErrProductionQualification
	}
	wire, readErr := io.ReadAll(io.LimitReader(reader, evidence.Bytes+1))
	if err := errors.Join(readErr, reader.Close()); err != nil {
		return nil, err
	}
	if int64(len(wire)) != evidence.Bytes || fmt.Sprintf("%x", sha256.Sum256(wire)) != evidence.SHA256 {
		return nil, fmt.Errorf("%w: retained stateful evidence bytes differ", release.ErrProductionQualification)
	}
	return wire, nil
}

stateful_declared.text:
func VerifyStatefulDeclared(ctx context.Context, bundle release.ContainerBundle, roots trust.Keyring, target release.ContainerTarget, now, until time.Time, evidence func(context.Context, string) (io.ReadCloser, error), allocations release.SequenceLocation) (VerifiedStateful, error) {
	container, err := release.VerifyContainerCurrent(ctx, bundle, roots, target, now, until, evidence, allocations)
	if err != nil {
		return VerifiedStateful{}, err
	}
	claim := container.Claim()
	_, imageDigest, _ := strings.Cut(claim.Image, "@sha256:")
	expected := release.ProductionExpectation{SourceRevision: claim.SourceRevision, ArtifactSHA256: imageDigest, QualificationSHA256: claim.QualificationSHA256, Cell: claim.Cell, Environment: claim.Environment, Runtime: release.ProductionRuntime, Architecture: claim.Architecture, Role: claim.Role}
	qualified, err := release.VerifyProductionCurrent(claim.Production.Qualification, claim.Production.Delegation, roots, expected, now)
	if err != nil {
		return VerifiedStateful{}, err
	}
	wire, err := readStatefulEvidence(ctx, evidence, qualified.Evidence[1], trust.MaxPayloadBytes)
	if err != nil {
		return VerifiedStateful{}, err
	}
	var declared StatefulQualification
	if err := protocol.DecodeStrict(wire, &declared, trust.MaxPayloadBytes); err != nil {
		return VerifiedStateful{}, err
	}
	return VerifyStatefulCurrent(ctx, bundle, roots, target, declared.Data, declared.TargetCPU, now, until, evidence, allocations)
}

retained_provenance.text:
func VerifyRetainedProvenance(ctx context.Context, bundle release.ContainerBundle, roots trust.Keyring,
	target release.ContainerTarget, expected RetainedData, evidence func(context.Context, string) (io.ReadCloser, error), allocations release.SequenceLocation,
) (RetainedData, error) {
	if ctx == nil || ctx.Err() != nil || target.Role != "terrabase" || evidence == nil {
		return RetainedData{}, ErrUnsafe
	}
	previous, err := release.VerifyContainerHistorical(bundle, roots, target)
	if err != nil {
		return RetainedData{}, err
	}
	claim := previous.Claim()
	_, imageDigest, _ := strings.Cut(claim.Image, "@sha256:")
	if claim.SourceTreeSHA256 != expected.SourceTreeSHA256 || imageDigest != expected.SourceArtifactSHA256 || claim.Architecture != expected.SourceArchitecture {
		return RetainedData{}, fmt.Errorf("%w: retained writer differs from recorded source", ErrUnsafe)
	}
	envelope, err := trust.DecodeEnvelope(bundle.Claim)
	if err != nil {
		return RetainedData{}, err
	}
	candidate := release.ProductionExpectation{SourceRevision: claim.SourceRevision, ArtifactSHA256: imageDigest, QualificationSHA256: claim.QualificationSHA256, Cell: target.Cell, Environment: target.Environment, Runtime: release.ProductionRuntime, Architecture: target.Architecture, Role: target.Role}
	// Verify at the authenticated release issue instant solely to recover prior
	// provenance after expiry; the current execution path verifies wall-clock time.
	qualification, err := release.VerifyProductionCurrent(claim.Production.Qualification, claim.Production.Delegation, roots, candidate, envelope.IssuedAt)
	if err != nil {
		return RetainedData{}, err
	}
	wire, err := readStatefulEvidence(ctx, evidence, qualification.Evidence[1], trust.MaxPayloadBytes)
	if err != nil {
		return RetainedData{}, err
	}
	var proof StatefulQualification
	if err := protocol.DecodeStrict(wire, &proof, trust.MaxPayloadBytes); err != nil {
		return RetainedData{}, err
	}
	verified, err := VerifyStatefulCurrent(ctx, bundle, roots, target, proof.Data, proof.TargetCPU, envelope.IssuedAt, envelope.IssuedAt.Add(time.Nanosecond), evidence, allocations)
	if err != nil {
		return RetainedData{}, err
	}
	result := verified.ResultData()
	comparison := result
	if expected.DiskFormatSHA256 == "" {
		comparison.DiskFormatSHA256 = ""
	}
	if comparison != expected {
		return RetainedData{}, fmt.Errorf("%w: retained signed result differs from current volume", ErrUnsafe)
	}
	return result, nil
}

native_provenance.text:
func VerifyNativeRetainedProvenance(ctx context.Context, bundle release.ContainerBundle, roots trust.Keyring, target release.ContainerTarget, expected RetainedData, now, until time.Time, evidence func(context.Context, string) (io.ReadCloser, error), allocations release.SequenceLocation) (RetainedData, error) {
	verified, err := VerifyStatefulDeclared(ctx, bundle, roots, target, now, until, evidence, allocations)
	if err != nil {
		return RetainedData{}, err
	}
	if !verified.nativeSource {
		return RetainedData{}, fmt.Errorf("%w: exact native source artifact evidence missing", ErrUnsafe)
	}
	data := verified.Data()
	comparison := data
	if expected.DiskFormatSHA256 == "" {
		comparison.DiskFormatSHA256 = ""
	}
	if expected.SourceArchitecture == "" {
		comparison.SourceArchitecture = ""
	}
	if comparison != expected {
		return RetainedData{}, fmt.Errorf("%w: native source or volume differs", ErrUnsafe)
	}
	return data, nil
}

allocation_fixture.text:
func statefulSequenceLocation(t *testing.T) release.SequenceLocation {
	t.Helper()
	directory := t.TempDir()
	var mu sync.Mutex
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !strings.HasPrefix(r.URL.Path, "/n/fixture/b/gru-1-head/o/") || r.Header.Get("Authorization") == "" {
			http.Error(w, "invalid signed allocation request", http.StatusForbidden)
			return
		}
		name := filepath.Join(directory, fmt.Sprintf("%x", sha256.Sum256([]byte(r.URL.Path))))
		mu.Lock()
		defer mu.Unlock()
		current, err := os.ReadFile(name)
		found := err == nil
		etag := fmt.Sprintf(`"%x"`, sha256.Sum256(current))
		switch r.Method {
		case http.MethodGet:
			if !found {
				http.NotFound(w, r)
				return
			}
			w.Header().Set("ETag", etag)
			_, _ = w.Write(current)
		case http.MethodPut:
			if r.Header.Get("If-None-Match") == "*" && found || r.Header.Get("If-Match") != "" && (!found || r.Header.Get("If-Match") != etag) {
				w.WriteHeader(http.StatusPreconditionFailed)
				return
			}
			if r.Header.Get("If-Match") == "" && r.Header.Get("If-None-Match") == "" {
				http.Error(w, "missing compare-and-swap", http.StatusBadRequest)
				return
			}
			body, err := io.ReadAll(io.LimitReader(r.Body, 64<<10))
			if err != nil {
				http.Error(w, "invalid body", http.StatusBadRequest)
				return
			}
			if err := os.WriteFile(name, body, 0o600); err != nil {
				http.Error(w, "persist allocation", http.StatusInternalServerError)
				return
			}
			w.WriteHeader(http.StatusOK)
		default:
			w.WriteHeader(http.StatusMethodNotAllowed)
		}
	}))
	t.Cleanup(server.Close)
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	keyPEM := pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})
	client, err := objectstorage.NewObjectStorageClientWithConfigurationProvider(common.NewRawConfigurationProvider("tenancy", "user", "sa-saopaulo-1", "fingerprint", string(keyPEM), nil))
	if err != nil {
		t.Fatal(err)
	}
	client.Host = server.URL
	transport := &http.Transport{DialContext: func(ctx context.Context, network, address string) (net.Conn, error) {
		if network != "tcp" || address != server.Listener.Addr().String() {
			t.Errorf("forbidden allocation fixture network dial: %s %s", network, address)
			return nil, errors.New("allocation fixture permits only its literal loopback listener")
		}
		return (&net.Dialer{}).DialContext(ctx, network, address)
	}}
	t.Cleanup(transport.CloseIdleConnections)
	loopback := &http.Client{Transport: transport, CheckRedirect: func(*http.Request, []*http.Request) error {
		return errors.New("allocation fixture rejects redirects")
	}}
	client.HTTPClient = statefulAllocationHTTPClient{server: server, client: loopback}
	policy := common.NoRetryPolicy()
	client.SetCustomClientConfiguration(common.CustomClientConfiguration{RetryPolicy: &policy})
	return release.SequenceLocation{Client: client, Namespace: "fixture", Bucket: "gru-1-head"}
}

allocation_transport.text:
func (client statefulAllocationHTTPClient) Do(request *http.Request) (*http.Response, error) {
	cloned := request.Clone(request.Context())
	address := *request.URL
	cloned.URL = &address
	cloned.URL.Scheme = "http"
	cloned.URL.Host = strings.TrimPrefix(client.server.URL, "http://")
	return client.client.Do(cloned)
}

container_current.text:
func VerifyContainerCurrent(ctx context.Context, bundle ContainerBundle, roots trust.Keyring, expected ContainerTarget, now, validUntil time.Time, evidence func(context.Context, string) (io.ReadCloser, error), allocations SequenceLocation) (VerifiedContainer, error) {
	if now.IsZero() || validUntil.Before(now) || !ValidRegion(expected.Cell) || !ValidEnvironment(expected.Environment) || !serviceRolePattern.MatchString(expected.Role) || expected.Architecture != "arm64" && expected.Architecture != "amd64" || evidence == nil {
		return VerifiedContainer{}, errors.New("container verification requires admitted target, current time, deadline and evidence store")
	}
	envelope, err := trust.DecodeEnvelope(bundle.Claim)
	if err != nil {
		return VerifiedContainer{}, err
	}
	policy := trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime}
	verify := func(at time.Time) ([]byte, error) {
		if len(bundle.Delegation) == 0 {
			return trust.VerifyCurrent(envelope, ContainerScope(expected), roots, at, policy)
		}
		grant, err := trust.DecodeEnvelope(bundle.Delegation)
		if err != nil {
			return nil, err
		}
		delegation, err := trust.VerifyDelegationCurrent(grant, roots, at, policy)
		if err != nil {
			return nil, err
		}
		return trust.VerifyDelegatedCurrent(envelope, ContainerScope(expected), delegation, at, policy)
	}
	payload, err := verify(now)
	if err != nil {
		return VerifiedContainer{}, err
	}
	if _, err := verify(validUntil); err != nil {
		return VerifiedContainer{}, err
	}
	verified, err := verifyContainerIdentity(bundle, roots, expected, envelope, payload)
	if err != nil {
		return VerifiedContainer{}, err
	}
	verified.familyEvidence, err = allocations.readWorkerFamily(ctx, roots, verified)
	if err != nil {
		return VerifiedContainer{}, err
	}
	claim := verified.claim
	_, imageDigest, _ := strings.Cut(claim.Image, "@sha256:")
	candidate := ProductionExpectation{SourceRevision: claim.SourceRevision, ArtifactSHA256: imageDigest, QualificationSHA256: claim.QualificationSHA256, Cell: expected.Cell, Environment: expected.Environment, Runtime: ProductionRuntime, Architecture: expected.Architecture, Role: expected.Role}
	proof, err := VerifyProductionCurrent(claim.Production.Qualification, claim.Production.Delegation, roots, candidate, now)
	if err != nil {
		return VerifiedContainer{}, err
	}
	if _, err := VerifyProductionCurrent(claim.Production.Qualification, claim.Production.Delegation, roots, candidate, validUntil); err != nil {
		return VerifiedContainer{}, err
	}
	for _, retained := range proof.Evidence {
		reader, err := evidence(ctx, retained.SHA256)
		if err != nil {
			return VerifiedContainer{}, fmt.Errorf("read qualification evidence: %w", err)
		}
		if reader == nil {
			return VerifiedContainer{}, errors.New("qualification evidence store returned no reader")
		}
		hash := sha256.New()
		n, readErr := io.Copy(hash, io.LimitReader(reader, retained.Bytes+1))
		closeErr := reader.Close()
		if err := errors.Join(readErr, closeErr); err != nil {
			return VerifiedContainer{}, err
		}
		if n != retained.Bytes || fmt.Sprintf("%x", hash.Sum(nil)) != retained.SHA256 {
			return VerifiedContainer{}, errors.New("container qualification evidence bytes differ from signed proof")
		}
	}
	qualificationEnvelope, err := trust.DecodeEnvelope(claim.Production.Qualification)
	if err != nil {
		return VerifiedContainer{}, err
	}
	verified.issuedAt = envelope.IssuedAt
	if qualificationEnvelope.IssuedAt.After(verified.issuedAt) {
		verified.issuedAt = qualificationEnvelope.IssuedAt
	}
	verified.expiresAt = validUntil
	for _, expires := range []time.Time{envelope.ExpiresAt, qualificationEnvelope.ExpiresAt} {
		if expires.Before(verified.expiresAt) {
			verified.expiresAt = expires
		}
	}
	return verified, nil
}

sequence_allocate.text:
func (location SequenceLocation) AllocateWithEvidence(ctx context.Context, identity SequenceIdentity, roots trust.Keyring, signer ed25519.PrivateKey) (uint64, []byte, error) {
	head, err := location.allocate(ctx, identity, roots, signer)
	if err != nil {
		return 0, nil, err
	}
	wire, err := location.retainReservation(ctx, head, roots)
	if err != nil {
		return 0, nil, err
	}
	return head.Sequence, wire, nil
}

sequence_import.text:
func (location SequenceLocation) ImportMigration(ctx context.Context, envelope trust.Envelope, roots trust.Keyring, role, environment string, now time.Time) error {
	migration, err := VerifySequenceMigrationHistorical(envelope, roots, role, environment)
	if err != nil {
		return err
	}
	if migration.Namespace != location.Namespace || migration.Bucket != location.Bucket {
		return fmt.Errorf("%w: migration sequence location", ErrInvalidReceipt)
	}
	head, etag, found, err := location.read(ctx, role, environment, roots)
	if err != nil {
		return err
	}
	if found {
		existing, _ := trust.Fingerprint(head.Migration)
		incoming, _ := trust.Fingerprint(envelope)
		if existing == incoming {
			return nil
		}
		return fmt.Errorf("%w: namespace already migrated", ErrSequenceConflict)
	}
	if _, err := VerifySequenceMigrationCurrent(envelope, roots, role, environment, now); err != nil {
		return err
	}
	err = location.write(ctx, role, environment, sequenceHead{Schema: "terrascale.release.sequence.v1", Sequence: migration.SequenceFloor, Migration: envelope}, etag)
	if !errors.Is(err, ErrSequenceConflict) {
		return err
	}
	// Another producer may initialize the exact same grant concurrently.
	head, _, found, err = location.read(ctx, role, environment, roots)
	if err != nil {
		return err
	}
	if found {
		retained, _ := trust.Fingerprint(head.Migration)
		incoming, _ := trust.Fingerprint(envelope)
		if retained == incoming {
			return nil
		}
	}
	return ErrSequenceConflict
}

sequence_read.text:
func (location SequenceLocation) read(ctx context.Context, role, environment string, roots trust.Keyring) (sequenceHead, string, bool, error) {
	var head sequenceHead
	if location.Client == nil || location.Namespace == "" || location.Bucket == "" {
		return head, "", false, fmt.Errorf("%w: sequence location", ErrInvalidReceipt)
	}
	name := SequenceObject(role, environment)
	response, err := ociclient.ReadObject(ctx, location.Client, objectstorage.GetObjectRequest{NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name})
	if sequenceHTTPStatus(err) == http.StatusNotFound {
		return head, "", false, nil
	}
	if err != nil {
		return head, "", false, err
	}
	defer response.Content.Close()
	wire, err := io.ReadAll(io.LimitReader(response.Content, trust.MaxEnvelopeBytes+1))
	if err != nil {
		return head, "", false, err
	}
	head, err = verifySequenceHead(wire, roots, role, environment)
	if err != nil {
		return head, "", false, err
	}
	migration, err := VerifySequenceMigrationHistorical(head.Migration, roots, role, environment)
	if err != nil {
		return head, "", false, err
	}
	if migration.Namespace != location.Namespace || migration.Bucket != location.Bucket || response.ETag == nil || *response.ETag == "" {
		return head, "", false, fmt.Errorf("%w: migration sequence location or ETag", ErrInvalidReceipt)
	}
	return head, *response.ETag, true, nil
}

sequence_write.text:
func (location SequenceLocation) write(ctx context.Context, role, environment string, head sequenceHead, etag string) error {
	wire, err := json.Marshal(head, json.Deterministic(true))
	if err != nil {
		return err
	}
	name := SequenceObject(role, environment)
	request := objectstorage.PutObjectRequest{NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name, ContentLength: new(int64(len(wire))), PutObjectBody: io.NopCloser(bytes.NewReader(wire)), ContentType: new("application/json")}
	if etag == "" {
		request.IfNoneMatch = new("*")
	} else {
		request.IfMatch = &etag
	}
	_, err = location.Client.PutObject(ctx, request)
	if sequenceHTTPStatus(err) == http.StatusPreconditionFailed {
		return ErrSequenceConflict
	}
	return err
}

family_read.text:
func (location SequenceLocation) readWorkerFamily(ctx context.Context, roots trust.Keyring, verified VerifiedContainer) ([]byte, error) {
	migration := verified.migration
	if location.Client == nil || location.Namespace != migration.Namespace || location.Bucket != migration.Bucket {
		return nil, errors.New("worker family reader differs from root-authorized sequence location")
	}
	claim := verified.claim
	name := SequenceReservationObject(claim.Role, claim.Environment, claim.SequenceMigrationSHA256, claim.ReleaseSequence)
	response, err := ociclient.ReadObject(ctx, location.Client, objectstorage.GetObjectRequest{NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name})
	if err != nil {
		return nil, err
	}
	if response.Content == nil {
		return nil, errors.New("worker family allocation has no body")
	}
	defer response.Content.Close()
	wire, err := io.ReadAll(io.LimitReader(response.Content, MaxWorkerFamilyEvidenceBytes+1))
	if err != nil {
		return nil, err
	}
	if err := verifyWorkerFamilyEvidence(wire, roots, claim); err != nil {
		return nil, err
	}
	return wire, nil
}

netns.text:
func verifyHostNetworkNamespace(pid int) error {
	var actual, host unix.Stat_t
	if err := unix.Stat(fmt.Sprintf("/proc/%d/ns/net", pid), &actual); err != nil {
		return err
	}
	if err := unix.Stat("/proc/self/ns/net", &host); err != nil {
		return err
	}
	if actual.Dev != host.Dev || actual.Ino != host.Ino {
		return errors.New("actual member network namespace differs from the host")
	}
	return nil
}

entityid.text:
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

// Derive gives an idempotent operation a stable ULID. A zero timestamp marks
// derived identities as having no creation time; the 80 entropy bits bind the
// domain-separated input. New entities use New instead.
func Derive(domain string, values ...string) string {
	h := sha256.New()
	for _, value := range append([]string{domain}, values...) {
		var size [8]byte
		binary.BigEndian.PutUint64(size[:], uint64(len(value)))
		h.Write(size[:])
		h.Write([]byte(value))
	}
	return ulid.MustNew(0, bytes.NewReader(h.Sum(nil)[:10])).String()
}
